import type { AgentConversation } from '../app/src/data/data_types'

export type ActivityOrigin = { kind: 'card'; cardInternalId: string } | { kind: 'project' }
export type ActionActivityStatus = 'cancelled' | 'completed' | 'failed' | 'okButNotAfter'

export interface ActionSettings {
    agent: string
    model: string
    permissionMode: string
    thinkingLevel: string
}

export interface ActivityCommitReference {
    available?: boolean
    actionId?: string
    actionName?: string
    branch: string
    commit: string
    committedAt: string
    deletions: number
    filePaths: string[]
    filesChanged: number
    insertions: number
}

export interface AgentActivityDetails {
    agent?: string | null
    model?: string
    permissionMode?: string
    thinkingLevel?: string
    type: 'agent'
}

export interface CommandActivityDetails {
    command: string
    output: string
    type: 'command'
}

interface ActionActivityRecordBase {
    commits: ActivityCommitReference[]
    completedAt: string
    conversationIds: string[]
    details: AgentActivityDetails | CommandActivityDetails
    runId: string
    origin: ActivityOrigin
    rootActionId: string
    rootActionLabel: string
    startedAt: string
    status: ActionActivityStatus
    type?: undefined
}

export interface AgentActionActivityRecord extends ActionActivityRecordBase {
    details: AgentActivityDetails
    rootConversationId: string
}

export interface CommandActionActivityRecord extends ActionActivityRecordBase {
    details: CommandActivityDetails
    rootConversationId?: never
}

export type ActionActivityRecord = AgentActionActivityRecord | CommandActionActivityRecord

export interface SystemActivityRecord {
    commits: [ActivityCommitReference]
    completedAt: string
    label: string
    origin: ActivityOrigin
    type: 'system'
}

export type ActivityRecord = ActionActivityRecord | SystemActivityRecord

export interface CardActivityFile {
    actionSettings: Record<string, ActionSettings>
    conversations: Omit<AgentConversation, 'path'>[]
    origin: ActivityOrigin
    records: ActivityRecord[]
    version: 4
}

export function createActivityFile(origin: ActivityOrigin): CardActivityFile
export function parseActivityValue(value: unknown, expectedOrigin?: ActivityOrigin | null): CardActivityFile
export function parseActivityFile(content: string, expectedOrigin?: ActivityOrigin | null): CardActivityFile
export function migrateActivityValue(value: unknown, expectedOrigin?: ActivityOrigin | null): CardActivityFile
export function findActivityConversation(activity: CardActivityFile, conversationId: string): Omit<AgentConversation, 'path'>

const ACTIVITY_ID_PATTERN = /^[a-zA-Z0-9._-]+$/u

function normalizeFolderPath(folderPath) {
    return folderPath.replace(/\\/gu, '/').replace(/^\/+|\/+$/gu, '')
}

function requireActivityId(value, fieldName) {
    if (typeof value !== 'string' || value.length === 0) throw new Error(`Missing ${fieldName}`)
    if (!ACTIVITY_ID_PATTERN.test(value) || value === '.' || value === '..') throw new Error(`Invalid ${fieldName}: ${value}`)

    return value
}

export function projectActivityFolder(projectFolder) {
    if (typeof projectFolder !== 'string') throw new Error('Missing projectFolder')
    const normalizedProjectFolder = normalizeFolderPath(projectFolder)

    return normalizedProjectFolder.length > 0 ? `${normalizedProjectFolder}/activity` : 'activity'
}

export function cardActivityFileName(cardInternalId) {
    return `card__${requireActivityId(cardInternalId, 'cardInternalId')}.json`
}

export function projectActivityFileName() {
    return 'project.json'
}

export function activityFilePath(projectFolder, origin) {
    if (!origin || typeof origin !== 'object') throw new Error('Missing activity origin')
    const fileName = origin.kind === 'card'
        ? cardActivityFileName(origin.cardInternalId)
        : origin.kind === 'project' ? projectActivityFileName() : null
    if (!fileName) throw new Error(`Invalid activity origin kind: ${String(origin.kind)}`)

    return `${projectActivityFolder(projectFolder)}/${fileName}`
}

export function conversationActivityReference(activityPath, conversationId) {
    if (typeof activityPath !== 'string' || activityPath.length === 0) throw new Error('Missing activity path')
    const id = requireActivityId(conversationId, 'conversationId')

    return `${activityPath}#conversation=${id}`
}

export function parseConversationActivityReference(reference) {
    if (typeof reference !== 'string' || reference.length === 0) throw new Error('Missing conversation activity reference')
    const marker = '#conversation='
    const markerIndex = reference.lastIndexOf(marker)
    if (markerIndex <= 0) throw new Error(`Invalid conversation activity reference: ${reference}`)
    const activityPath = reference.slice(0, markerIndex)
    const conversationId = requireActivityId(reference.slice(markerIndex + marker.length), 'conversationId')

    return { activityPath, conversationId }
}

