const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');

const {
    LEGACY_ACTIVITY_VERSION,
    PREVIOUS_ACTIVITY_VERSION,
    SECOND_ACTIVITY_VERSION,
    createActivityFile,
    findActivityConversation,
    migrateActivityValue,
    parseActivityValue,
