                { content: 'done', id: 'assistant-1', kind: 'message', role: 'assistant', timestamp: '2026-08-01T12:01:00.000Z' },
            ],
            id: 'conversation-root', providerSessions: [], startedAt: '2026-08-01T12:00:00.000Z', status: 'completed', title: 'Build',
