        expect(migrated.records[0]).toMatchObject({
            conversationIds: ['conversation-child', 'conversation-root'],
            details: { agent: 'codex', model: 'gpt-5', thinkingLevel: 'high', type: 'agent' },
            rootConversationId: 'conversation-root',
