import { parseAgentConversation } from './agent_conversations.mjs'

const ACTIVITY_VERSION = 4
export const LEGACY_ACTIVITY_VERSION = 1
export const SECOND_ACTIVITY_VERSION = 2
export const PREVIOUS_ACTIVITY_VERSION = 3
const ACTION_ACTIVITY_STATUSES = new Set(['cancelled', 'completed', 'failed', 'okButNotAfter'])

function requiredString(value, fieldName, allowEmpty = false) {
    if (typeof value !== 'string' || (!allowEmpty && value.length === 0)) throw new Error(`Malformed activity file: missing ${fieldName}`)

    return value
}

function requiredTimestamp(value, fieldName) {
    const timestamp = requiredString(value, fieldName)
    if (Number.isNaN(Date.parse(timestamp))) throw new Error(`Malformed activity file: invalid ${fieldName}`)

    return timestamp
}

function nonNegativeInteger(value, fieldName) {
    if (!Number.isInteger(value) || value < 0) throw new Error(`Malformed activity file: invalid ${fieldName}`)

    return value
}

function requiredStringArray(value, fieldName) {
    if (!Array.isArray(value)) throw new Error(`Malformed activity file: invalid ${fieldName}`)

    return value.map((entry, index) => requiredString(entry, `${fieldName}[${index}]`))
}

function parseOrigin(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Malformed activity file: missing origin')
    if (value.kind === 'project') return { kind: 'project' }
    if (value.kind !== 'card') throw new Error(`Malformed activity file: invalid origin kind ${String(value.kind)}`)

    return { cardInternalId: requiredString(value.cardInternalId, 'origin.cardInternalId'), kind: 'card' }
}

function parseActionSettings(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
        throw new Error('Malformed activity file: actionSettings must be an object')
    }

    return Object.fromEntries(Object.entries(value).map(([actionId, settings]) => {
        if (actionId.length === 0) throw new Error('Malformed activity file: actionSettings action ID must not be empty')
        if (!settings || typeof settings !== 'object' || Array.isArray(settings)) {
            throw new Error(`Malformed activity file: invalid actionSettings.${actionId}`)
        }

        if (settings.accessLevel !== undefined || settings.approvalPolicy !== undefined) {
            throw new Error(`Malformed activity file: obsolete permission fields in actionSettings.${actionId}`)
        }

        return [actionId, {
            agent: requiredString(settings.agent, `actionSettings.${actionId}.agent`, true),
            model: requiredString(settings.model, `actionSettings.${actionId}.model`, true),
            permissionMode: requiredString(settings.permissionMode, `actionSettings.${actionId}.permissionMode`, true),
            thinkingLevel: requiredString(settings.thinkingLevel, `actionSettings.${actionId}.thinkingLevel`, true),
        }]
    }))
}

function sameOrigin(first, second) {
    return first.kind === second.kind && first.cardInternalId === second.cardInternalId
}

function parseCommit(value, index) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`Malformed activity file: invalid commits[${index}]`)
    const commit = {
        branch: requiredString(value.branch, `commits[${index}].branch`),
        commit: requiredString(value.commit, `commits[${index}].commit`),
        committedAt: requiredTimestamp(value.committedAt, `commits[${index}].committedAt`),
        deletions: nonNegativeInteger(value.deletions, `commits[${index}].deletions`),
        filePaths: requiredStringArray(value.filePaths, `commits[${index}].filePaths`),
        filesChanged: nonNegativeInteger(value.filesChanged, `commits[${index}].filesChanged`),
        insertions: nonNegativeInteger(value.insertions, `commits[${index}].insertions`),
    }
    if (!/^[0-9a-f]{40}$/iu.test(commit.commit)) throw new Error(`Malformed activity file: invalid commits[${index}].commit`)
    if (value.available !== undefined) {
        if (typeof value.available !== 'boolean') throw new Error(`Malformed activity file: invalid commits[${index}].available`)
        commit.available = value.available
    }
    if (value.actionId !== undefined || value.actionName !== undefined) {
        commit.actionId = requiredString(value.actionId, `commits[${index}].actionId`)
        commit.actionName = requiredString(value.actionName, `commits[${index}].actionName`)
    }

    return commit
}

function parseLegacyHistory(value, index) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`Malformed activity file: invalid records[${index}].history`)
    const status = requiredString(value.status, `records[${index}].history.status`)
    if (status !== 'completed' && status !== 'failed') throw new Error(`Malformed activity file: invalid records[${index}].history.status`)
    const history = {
        completedAt: requiredTimestamp(value.completedAt, `records[${index}].history.completedAt`),
        output: requiredString(value.output, `records[${index}].history.output`, true),
        prompt: requiredString(value.prompt, `records[${index}].history.prompt`, true),
        status,
    }
    for (const fieldName of ['accessLevel', 'agent', 'approvalPolicy', 'command', 'model', 'thinkingLevel']) {
        if (value[fieldName] === undefined) continue
        if (fieldName === 'agent' && value[fieldName] === null) history[fieldName] = null
        else history[fieldName] = requiredString(value[fieldName], `records[${index}].history.${fieldName}`)
    }

    return history
}

function parseAgentDetails(value, index) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`Malformed activity file: invalid records[${index}].details`)
    const details = { type: 'agent' }
    if (value.accessLevel !== undefined || value.approvalPolicy !== undefined) {
        throw new Error(`Malformed activity file: obsolete permission fields in records[${index}].details`)
    }
    for (const fieldName of ['agent', 'model', 'permissionMode', 'thinkingLevel']) {
        if (value[fieldName] === undefined) continue
        if (fieldName === 'agent' && value[fieldName] === null) details[fieldName] = null
        else details[fieldName] = requiredString(value[fieldName], `records[${index}].details.${fieldName}`)
    }

    return details
}

function parseCommandDetails(value, index) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`Malformed activity file: invalid records[${index}].details`)

    return {
        command: requiredString(value.command, `records[${index}].details.command`, true),
        output: requiredString(value.output, `records[${index}].details.output`, true),
        type: 'command',
    }
}

function parseDetails(value, index) {
    if (value?.type === 'agent') return parseAgentDetails(value, index)
    if (value?.type === 'command') return parseCommandDetails(value, index)

    throw new Error(`Malformed activity file: invalid records[${index}].details.type`)
}

function parseSystemRecord(value, index, activityOrigin) {
    if (!Array.isArray(value.commits) || value.commits.length !== 1) {
        throw new Error(`Malformed activity file: system records[${index}].commits must contain one commit`)
    }
    const origin = parseOrigin(value.origin)
    if (!sameOrigin(origin, activityOrigin)) throw new Error(`Malformed activity file: records[${index}].origin does not match activity origin`)

    return {
        commits: value.commits.map(parseCommit),
        completedAt: requiredTimestamp(value.completedAt, `records[${index}].completedAt`),
        label: requiredString(value.label, `records[${index}].label`),
        origin,
        type: 'system',
    }
}

function parseRecord(value, index, activityOrigin) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`Malformed activity file: invalid records[${index}]`)
    if (value.type === 'system') return parseSystemRecord(value, index, activityOrigin)
    const status = requiredString(value.status, `records[${index}].status`)
    if (!ACTION_ACTIVITY_STATUSES.has(status)) throw new Error(`Malformed activity file: invalid records[${index}].status`)
    if (!Array.isArray(value.commits)) throw new Error(`Malformed activity file: invalid records[${index}].commits`)
    if (!Array.isArray(value.conversationIds)) throw new Error(`Malformed activity file: invalid records[${index}].conversationIds`)

    const origin = parseOrigin(value.origin)
    if (!sameOrigin(origin, activityOrigin)) throw new Error(`Malformed activity file: records[${index}].origin does not match activity origin`)

    if (value.history !== undefined) throw new Error(`Malformed activity file: records[${index}].history is not supported`)
    const details = parseDetails(value.details, index)
    if (details.type === 'command' && value.rootConversationId !== undefined) {
        throw new Error(`Malformed activity file: command records[${index}] cannot have rootConversationId`)
    }
    const record = {
        commits: value.commits.map(parseCommit),
        completedAt: requiredTimestamp(value.completedAt, `records[${index}].completedAt`),
        conversationIds: requiredStringArray(value.conversationIds, `records[${index}].conversationIds`),
        details,
        runId: requiredString(value.runId, `records[${index}].runId`),
        origin,
        rootActionId: requiredString(value.rootActionId, `records[${index}].rootActionId`),
        rootActionLabel: requiredString(value.rootActionLabel, `records[${index}].rootActionLabel`),
        startedAt: requiredTimestamp(value.startedAt, `records[${index}].startedAt`),
        status,
    }
    if (details.type === 'agent') record.rootConversationId = requiredString(value.rootConversationId, `records[${index}].rootConversationId`)

    return record
}

function parseLegacyRecord(value, index, activityOrigin) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`Malformed activity file: invalid records[${index}]`)
    if (value.type === 'system') return parseSystemRecord(value, index, activityOrigin)
    const status = requiredString(value.status, `records[${index}].status`)
    if (!ACTION_ACTIVITY_STATUSES.has(status)) throw new Error(`Malformed activity file: invalid records[${index}].status`)
    if (!Array.isArray(value.commits)) throw new Error(`Malformed activity file: invalid records[${index}].commits`)
    const origin = parseOrigin(value.origin)
    if (!sameOrigin(origin, activityOrigin)) throw new Error(`Malformed activity file: records[${index}].origin does not match activity origin`)

    return {
        commits: value.commits.map(parseCommit),
        completedAt: requiredTimestamp(value.completedAt, `records[${index}].completedAt`),
        conversationIds: requiredStringArray(value.conversationIds, `records[${index}].conversationIds`),
        history: parseLegacyHistory(value.history, index),
        origin,
        rootActionId: requiredString(value.rootActionId, `records[${index}].rootActionId`),
        rootActionLabel: requiredString(value.rootActionLabel, `records[${index}].rootActionLabel`),
        runId: requiredString(value.runId, `records[${index}].runId`),
        startedAt: requiredTimestamp(value.startedAt, `records[${index}].startedAt`),
        status,
    }
}

function parseConversation(value, index, activityOrigin) {
    try {
        const parsed = parseAgentConversation(JSON.stringify(value), '')
        const expectedCardInternalId = activityOrigin.kind === 'card' ? activityOrigin.cardInternalId : null
        if (parsed.cardInternalId !== expectedCardInternalId) throw new Error('conversation cardInternalId does not match activity origin')

        return Object.fromEntries(Object.entries(parsed).filter(([fieldName]) => fieldName !== 'path'))
    } catch (error) {
        const detail = error instanceof Error ? error.message : 'invalid conversation'
        throw new Error(`Malformed activity file: conversations[${index}] ${detail}`, { cause: error })
    }
}

export function createActivityFile(origin) {
    return { actionSettings: {}, conversations: [], origin: parseOrigin(origin), records: [], version: ACTIVITY_VERSION }
}

export function parseActivityValue(value, expectedOrigin = null) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Malformed activity file: root must be an object')
    if (value.version !== ACTIVITY_VERSION) throw new Error(`Malformed activity file: unsupported version ${String(value.version)}`)
    if (!Array.isArray(value.records)) throw new Error('Malformed activity file: records must be an array')
    if (!Array.isArray(value.conversations)) throw new Error('Malformed activity file: conversations must be an array')
    const actionSettings = parseActionSettings(value.actionSettings)
    const origin = parseOrigin(value.origin)
    if (expectedOrigin) {
        const expected = parseOrigin(expectedOrigin)
        if (!sameOrigin(origin, expected)) {
            throw new Error('Malformed activity file: origin does not match requested activity')
        }
    }

    const conversations = value.conversations.map((conversation, index) => parseConversation(conversation, index, origin))
    const records = value.records.map((record, index) => parseRecord(record, index, origin))
    for (const [index, record] of records.entries()) {
        if (record.type === 'system' || record.details.type !== 'agent') continue
        if (!record.conversationIds.includes(record.rootConversationId)) {
            throw new Error(`Malformed activity file: records[${index}].rootConversationId is not in conversationIds`)
        }
        const conversation = conversations.find(({ id }) => id === record.rootConversationId)
        if (!conversation) throw new Error(`Malformed activity file: records[${index}].rootConversationId does not resolve`)
        if (conversation.actionId !== record.rootActionId) {
            throw new Error(`Malformed activity file: records[${index}].rootConversationId action does not match rootActionId`)
        }
    }

    return {
        actionSettings,
        conversations,
        origin,
        records,
        version: ACTIVITY_VERSION,
    }
}

function legacyPermissionMode(agent, accessLevel, approvalPolicy, fieldName) {
    if (accessLevel === undefined && approvalPolicy === undefined) return undefined
    if (agent === 'codex' && accessLevel === 'workspace-write' && approvalPolicy === 'on-request') return 'ask-for-approval'
    if (agent === 'codex' && accessLevel === 'danger-full-access' && approvalPolicy === 'never') return 'full-access'
    if (agent === 'claude' && (accessLevel === undefined || accessLevel === '')) {
        if (approvalPolicy === 'acceptEdits') return 'ask-for-approval'
        if (approvalPolicy === 'auto') return 'approve-for-me'
        if (approvalPolicy === 'bypassPermissions') return 'full-access'
    }

    throw new Error(`Cannot migrate activity file: unrecognised legacy permission combination in ${fieldName}`)
}

function migrateVersionThreeActionSettings(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
        throw new Error('Malformed activity file: actionSettings must be an object')
    }

    return Object.fromEntries(Object.entries(value).map(([actionId, settings]) => {
        if (!settings || typeof settings !== 'object' || Array.isArray(settings)) {
            throw new Error(`Malformed activity file: invalid actionSettings.${actionId}`)
        }
        const permissionMode = legacyPermissionMode(
            settings.agent,
            settings.accessLevel,
            settings.approvalPolicy,
            `actionSettings.${actionId}`,
        )

        return [actionId, {
            agent: requiredString(settings.agent, `actionSettings.${actionId}.agent`, true),
            model: requiredString(settings.model, `actionSettings.${actionId}.model`, true),
            ...(permissionMode !== undefined ? { permissionMode } : { permissionMode: '' }),
            thinkingLevel: requiredString(settings.thinkingLevel, `actionSettings.${actionId}.thinkingLevel`, true),
        }]
    }))
}

function migrateLegacyRecord(record, index, conversations) {
    if (record.type === 'system') return record
    const { history, ...base } = record
    const agentRecord = history.agent !== undefined
        || history.accessLevel !== undefined
        || history.approvalPolicy !== undefined
        || history.model !== undefined
        || history.thinkingLevel !== undefined
    if (!agentRecord) {
        return {
            ...base,
            details: { command: history.command ?? '', output: history.output, type: 'command' },
        }
    }

    const candidates = conversations.filter((conversation) => (
        record.conversationIds.includes(conversation.id) && conversation.actionId === record.rootActionId
    ))
    if (candidates.length !== 1) {
        throw new Error(`Cannot migrate activity file: agent records[${index}] has ${candidates.length} matching root conversations`)
    }
    const permissionMode = legacyPermissionMode(
        history.agent,
        history.accessLevel,
        history.approvalPolicy,
        `records[${index}].history`,
    )
    const details = Object.fromEntries(Object.entries({
        agent: history.agent,
        model: history.model,
        permissionMode,
        thinkingLevel: history.thinkingLevel,
        type: 'agent',
    }).filter(([, fieldValue]) => fieldValue !== undefined))

    return { ...base, details, rootConversationId: candidates[0].id }
}

function migrateVersionThreeRecord(record, index) {
    if (record.type === 'system' || record.details?.type !== 'agent') return record
    const { accessLevel, approvalPolicy, ...details } = record.details
    const permissionMode = legacyPermissionMode(details.agent, accessLevel, approvalPolicy, `records[${index}].details`)

    return {
        ...record,
        details: { ...details, ...(permissionMode !== undefined ? { permissionMode } : {}) },
    }
}

export function migrateActivityValue(value, expectedOrigin = null) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Malformed activity file: root must be an object')
    if (![LEGACY_ACTIVITY_VERSION, SECOND_ACTIVITY_VERSION, PREVIOUS_ACTIVITY_VERSION].includes(value.version)) {
        throw new Error(`Cannot migrate activity file version ${String(value.version)}`)
    }
    if (value.version === PREVIOUS_ACTIVITY_VERSION || value.version === SECOND_ACTIVITY_VERSION) {
        const actionSettings = value.version === PREVIOUS_ACTIVITY_VERSION
            ? migrateVersionThreeActionSettings(value.actionSettings)
            : {}
        const records = value.records.map(migrateVersionThreeRecord)

        return parseActivityValue({ ...value, actionSettings, records, version: ACTIVITY_VERSION }, expectedOrigin)
    }
    if (!Array.isArray(value.records)) throw new Error('Malformed activity file: records must be an array')
    if (!Array.isArray(value.conversations)) throw new Error('Malformed activity file: conversations must be an array')
    const origin = parseOrigin(value.origin)
    if (expectedOrigin && !sameOrigin(origin, parseOrigin(expectedOrigin))) {
        throw new Error('Malformed activity file: origin does not match requested activity')
    }
    const conversations = value.conversations.map((conversation, index) => parseConversation(conversation, index, origin))
    const legacyRecords = value.records.map((record, index) => parseLegacyRecord(record, index, origin))
    const migrated = {
        actionSettings: {},
        conversations,
        origin,
        records: legacyRecords.map((record, index) => migrateLegacyRecord(record, index, conversations)),
        version: ACTIVITY_VERSION,
    }

    return parseActivityValue(migrated, expectedOrigin)
}

export function parseActivityFile(content, expectedOrigin = null) {
    return parseActivityValue(JSON.parse(content), expectedOrigin)
}

export function findActivityConversation(activity, conversationId) {
    const conversation = activity.conversations.find(({ id }) => id === conversationId)
    if (!conversation) throw new Error(`Activity conversation not found: ${conversationId}`)
    return conversation
}

import { AUTO_COMMIT_DELAY_MS, type CommitRequest, type MarkdownFile } from './data_types'

import { markdownParsingService } from '../services/data/markdown_parsing_service'
import type { OpenDocumentSaveReference } from '../services/open_files_service'
import type { Card } from './data_types'

type DelayId = number

interface CommitBatcherOperations {
    commitFiles(request: CommitRequest): Promise<unknown>
    pushCommittedFiles(request: CommitRequest): Promise<unknown>
    requireCardByInternalId(internalId: string): Card
}

export const COMMIT_BATCHER_FLUSH_FAILED_EVENT = 'flushFailed'
export const COMMIT_BATCHER_PENDING_CHANGED_EVENT = 'pendingChanged'

interface PendingFileChange {
    change: CommitChange
    fromPath: string
    moveSource: boolean
    onCommitted?: (fromPath: string, toPath: string) => void
    onPersisted?: () => void
    saveReference?: OpenDocumentSaveReference
}

export interface CommitFileChange extends MarkdownFile {
    onPersisted?: () => void
    saveReference?: OpenDocumentSaveReference
}

export interface CommitCardChange {
    cardInternalId: string
    onPersisted?: () => void
    path: string
    saveReference?: OpenDocumentSaveReference
    targetPath?: string
}

export type CommitChange = CommitFileChange | CommitCardChange

function isCardChange(change: CommitChange): change is CommitCardChange {
    return 'cardInternalId' in change
}

function changePath(change: CommitChange) {
    return isCardChange(change) ? change.targetPath ?? change.path : change.path
}

interface SerializedChange {
    card: Card | null
    file: MarkdownFile
}

function serializeChange(change: CommitChange, cardOperations: CommitBatcherOperations): SerializedChange {
    if (!isCardChange(change)) {
        const file = {
            content: change.content,
            ...(change.encoding ? { encoding: change.encoding } : {}),
            path: change.path,
            ...(change.sha ? { sha: change.sha } : {}),
        }

        return { card: null, file }
    }

    const card = cardOperations.requireCardByInternalId(change.cardInternalId)
    const file = { ...markdownParsingService.serializeCard(card), path: changePath(change) }

    return { card, file }
}

export class CommitBatcher extends EventTarget {
    private activeFlush: Promise<void> | null
    private automaticFlushDeferrals: number
    private readonly cardOperations: CommitBatcherOperations
    private readonly delayMs
    private pendingBranch: string | null
    private readonly pendingChanges
    private readonly pendingMessagesByPath
    private scheduledDelayId: DelayId | null

    constructor(cardOperations: CommitBatcherOperations, delayMs = AUTO_COMMIT_DELAY_MS) {
        super()
        this.activeFlush = null
        this.automaticFlushDeferrals = 0
        this.cardOperations = cardOperations
        this.delayMs = delayMs
        this.pendingBranch = null
        this.pendingChanges = new Map<string, PendingFileChange>()
        this.pendingMessagesByPath = new Map<string, string[]>()
        this.scheduledDelayId = null
    }

    schedule(branch: string, changes: CommitChange[], message: string) {
        this.pendingBranch = branch
        changes.forEach((change) => {
            const path = changePath(change)
            this.pendingChanges.set(path, {
                change,
                fromPath: path,
                moveSource: false,
                onPersisted: change.onPersisted,
                saveReference: change.saveReference,
            })
            this.addPendingMessage(path, message)
        })

        this.scheduleFlush()
    }

    schedulePathChange(
        branch: string,
        fromPath: string,
        change: CommitChange,
        message: string,
        onCommitted: (fromPath: string, toPath: string) => void,
        sourceExists = true,
    ) {
        this.pendingBranch = branch
        this.pendingChanges.set(fromPath, {
            change,
            fromPath,
            moveSource: sourceExists,
            onCommitted,
            onPersisted: change.onPersisted,
            saveReference: change.saveReference,
        })
        this.addPendingMessage(fromPath, message)

        this.scheduleFlush()
    }

    private scheduleFlush() {
        this.clearScheduledDelay()
        if (this.automaticFlushDeferrals > 0) {
            this.dispatchEvent(new Event(COMMIT_BATCHER_PENDING_CHANGED_EVENT))
            return
        }
        this.scheduledDelayId = window.setTimeout(this.createFlushCallback(), this.delayMs)
        this.dispatchEvent(new Event(COMMIT_BATCHER_PENDING_CHANGED_EVENT))
    }

    /** Pauses timer-driven flushes while one caller adds fields that must share a card version. */
    deferAutomaticFlush() {
        this.automaticFlushDeferrals += 1
        this.clearScheduledDelay()
        let released = false

        return () => {
            if (released) return

            released = true
            this.automaticFlushDeferrals -= 1
            if (this.automaticFlushDeferrals === 0 && this.hasPending()) this.scheduleFlush()
        }
    }

    hasPending() {
        return this.pendingChanges.size > 0 && this.pendingBranch !== null
    }

    hasPendingFile(path: string) {
        return [...this.pendingChanges.values()].some(({ change, fromPath }) => (
            fromPath === path || changePath(change) === path
        ))
    }

    discardPendingFile(path: string) {
        const entry = [...this.pendingChanges.entries()].find(([, { change, fromPath }]) => (
            fromPath === path || changePath(change) === path
        ))
        if (!entry) return

        const [changeKey] = entry
        this.pendingChanges.delete(changeKey)

        this.pendingMessagesByPath.delete(changeKey)
        if (this.pendingChanges.size === 0) {
            this.pendingBranch = null
            this.clearScheduledDelay()
        }
        this.dispatchEvent(new Event(COMMIT_BATCHER_PENDING_CHANGED_EVENT))
    }

    async flush() {
        if (this.activeFlush) {
            await this.activeFlush
            if (this.hasPending()) await this.flush()
            return
        }
        if (!this.hasPending()) return

        this.clearScheduledDelay()
        const pendingChanges = [...this.pendingChanges.values()]
        const serializedChanges = new Map(
            pendingChanges.map((change) => [change, serializeChange(change.change, this.cardOperations)]),
        )
        const files = pendingChanges
            .filter(({ moveSource }) => !moveSource)
            .map((change) => (serializedChanges.get(change) as SerializedChange).file)
        const moves = pendingChanges
            .filter(({ moveSource }) => moveSource)
            .map((change) => {
                const { file } = serializedChanges.get(change) as SerializedChange

                return {
                    content: file.content,
                    ...(file.encoding ? { encoding: file.encoding } : {}),
                    fromPath: change.fromPath,
                    ...(file.sha ? { sha: file.sha } : {}),
                    toPath: file.path,
                }
            })
        const request = {
            branch: this.pendingBranch as string,
            files,
            message: this.createCommitMessage(),
            ...(moves.length > 0 ? { moves } : {}),
        }

        this.activeFlush = this.commitSnapshot(request, pendingChanges, serializedChanges)
        try {
            await this.activeFlush
        } finally {
            this.activeFlush = null
        }
    }

    private addPendingMessage(path: string, message: string) {
        const messages = this.pendingMessagesByPath.get(path) ?? []
        if (messages.includes(message)) return

        this.pendingMessagesByPath.set(path, [...messages, message])
    }

    private async commitSnapshot(
        request: CommitRequest,
        changes: PendingFileChange[],
        serializedChanges: Map<PendingFileChange, SerializedChange>,
    ) {
        await this.cardOperations.commitFiles(request)
        for (const change of changes) {
            const { fromPath, onCommitted, onPersisted, saveReference } = change
            const { card, file } = serializedChanges.get(change) as SerializedChange
            const current = this.pendingChanges.get(fromPath)
            if (current === change) {
                this.pendingChanges.delete(fromPath)
                this.pendingMessagesByPath.delete(fromPath)
            } else if (current && file.path !== fromPath) {
                this.pendingChanges.delete(fromPath)
                this.pendingChanges.set(file.path, { ...current, fromPath: file.path, moveSource: true })
                const messages = this.pendingMessagesByPath.get(fromPath)
                this.pendingMessagesByPath.delete(fromPath)
                if (messages) this.pendingMessagesByPath.set(file.path, messages)
            }
            if (card) markdownParsingService.acknowledgeSerializedCard(card, file)
            saveReference?.acknowledge()
            onPersisted?.()
            onCommitted?.(fromPath, file.path)
        }
        if (this.pendingChanges.size === 0) this.pendingBranch = null
        this.dispatchEvent(new Event(COMMIT_BATCHER_PENDING_CHANGED_EVENT))
        await this.cardOperations.pushCommittedFiles(request)
    }

    private createCommitMessage() {
        const messages = [...this.pendingMessagesByPath.values()].flat()
        const distinctMessages = [...new Set(messages)]
        if (distinctMessages.length === 1) return distinctMessages[0]

        const body = distinctMessages.map((message) => `- ${message}`).join('\n')

        return `Update ${this.pendingChanges.size} files\n\n${body}`
    }

    private createFlushCallback() {
        return () => {
            void this.flush().catch((error: unknown) => {
                this.dispatchEvent(new CustomEvent(COMMIT_BATCHER_FLUSH_FAILED_EVENT, { detail: error }))
            })
        }
    }

    private clearScheduledDelay() {
        if (this.scheduledDelayId === null) return

        window.clearTimeout(this.scheduledDelayId)
        this.scheduledDelayId = null
    }
}

import {
    COMMIT_BATCHER_FLUSH_FAILED_EVENT,
    COMMIT_BATCHER_PENDING_CHANGED_EVENT,
    CommitBatcher,
} from '../../data/commit_batcher'
import type { ActionContext } from '../../data/action_context'
import { resolveProjectConfigPaths, type MarkdownFile, type ProjectConfig, type ProjectReference, type ProjectSnapshot, type RunningAgent, type StorageService } from '../../data/data_types'
import type { RemarkableBridge } from '../../data/remarkable_bridge'
import { agentAcknowledgementService } from '../agents/agent_acknowledgement_service'
import { agentConversationService, loadAgentConversation } from '../agents/agent_conversation_service'
import { CardOperations, type CardOperationsDeps } from './card_operations'
import { configService } from '../config/config_service'
import { type DataServiceDependencies, getProjectConfigOrNull, reportCommitFlushFailure } from './data_service_context'
import { notifyActionCardStateChange } from '../actions/action_run_registry'
import { AgentIntegration, type AgentIntegrationDeps } from '../agents/agent_integration'
import { ProjectLoading, type ProjectLoadingDeps } from '../project/project_loading'
import { ProjectState } from '../project/project_state'
import { ReleaseOperations, type ReleaseOperationsDeps } from '../release_operations'
import { SaveStateService, withSaveStateTracking } from '../project/save_state_service'
import { getRemarkableMetadataContent, importRemarkableImages, type RemarkableImportInput } from '../remarkable/remarkable_import_service'
import type { RemarkableImportPlan } from '../remarkable/remarkable_import_service'
import { getService, register } from '../service_injector'
import { telemetryService } from '../telemetry/telemetry_service'
import { worktreeService } from '../project/worktree_service'
import { mergeConflictService } from '../project/merge_conflict_service'
import { dialogService } from '../dialog_service'
import type { CardParseError } from './markdown_parsing_service'
import type { OpenDocumentSaveReference } from '../open_files_service'
import { CARD_CHANGED_EVENT, CARD_FIELDS, cardCollectionFieldChangedEvent, cardFieldChangedEvent, type CardField } from './card_events'

export { CARD_CHANGED_EVENT, cardCollectionFieldChangedEvent, cardFieldChangedEvent } from './card_events'
export type { CardField } from './card_events'

export type { RemarkableImportInput }
export interface DataServiceState {
    project: ProjectReference | null
    runningAgents: RunningAgent[]
    snapshot: ProjectSnapshot | null
}

export interface DataPersistenceSnapshot {
    hasPendingFileCommit: boolean
    hasPendingPush: boolean
    isSaving: boolean
}

export interface CardAddedEventDetail {
    card: ProjectSnapshot['activeCards'][number]
}

export interface CardChangedEventDetail extends CardAddedEventDetail {
    previousCard: ProjectSnapshot['activeCards'][number]
}

export interface CardRemovedEventDetail {
    card: ProjectSnapshot['activeCards'][number]
}

export interface CardPathChangedEventDetail {
    fromPath: string
    toPath: string
}

export const CARD_ADDED_EVENT = 'cardAdded'
export const CARD_PATH_CHANGED_EVENT = 'cardPathChanged'
export const CARD_REMOVED_EVENT = 'cardRemoved'

function reportCardParseErrors(errors: CardParseError[]) {
    const paths = errors.map(({ path }) => path).join(', ')
    dialogService.warning(`Some project files could not be loaded and were skipped: ${paths}`, { title: 'Some cards were not loaded' })
    errors.forEach(({ error }) => telemetryService.captureError(error))
}

function eventCard(card: ProjectSnapshot['activeCards'][number]) {
    return {
        ...card,
        header: {
            ...card.header,
            affects: [...card.header.affects],
            agentLogReferences: [...card.header.agentLogReferences],
            policy: { ...card.header.policy },
        },
    }
}

function isSameArray<T>(first: readonly T[], second: readonly T[]) {
    return first === second || (first.length === second.length && second.every((value, index) => first[index] === value))
}

function isSamePolicy(first: Record<string, boolean>, second: Record<string, boolean>) {
    if (first === second) return true
    const entries = Object.entries(second)

    return Object.keys(first).length === entries.length && entries.every(([key, value]) => first[key] === value)
}

function cardFieldChanged(field: CardField, previousCard: CardAddedEventDetail['card'], card: CardAddedEventDetail['card']) {
    const previousHeader = previousCard.header
    const header = card.header
    if (field === 'affects') return !isSameArray(previousHeader.affects, header.affects)
    if (field === 'body') return previousCard.content !== card.content
    if (field === 'conversation') {
        return !isSameArray(previousCard.agentConversations, card.agentConversations)
            || !isSameArray(previousCard.agentConversationErrors, card.agentConversationErrors)
            || !isSameArray(previousHeader.agentLogReferences, header.agentLogReferences)
    }
    if (field === 'identity') {
        return previousHeader.id !== header.id
            || previousHeader.internalId !== header.internalId
            || previousCard.isActive !== card.isActive
            || previousCard.path !== card.path
    }
    if (field === 'ordering') return previousHeader.after !== header.after || previousHeader.status !== header.status
    if (field === 'policy') return !isSamePolicy(previousHeader.policy, header.policy)
    if (field === 'status') return previousHeader.status !== header.status
    if (field === 'title') return previousHeader.title !== header.title

    return previousHeader.worktree !== header.worktree
        || previousHeader.worktreeError !== header.worktreeError
        || previousHeader.worktreeValue !== header.worktreeValue
}

async function flushAggregatePendingChanges() {
    const persistenceService = getService<{ flushPendingChanges(): Promise<void> }>('projectPersistenceService')
    await persistenceService.flushPendingChanges()
}

export class DataService extends EventTarget {
    readonly agents: AgentIntegration
    readonly cards: CardOperations
    readonly projectLoading: ProjectLoading
    readonly releases: ReleaseOperations

    private commitBatcher: CommitBatcher | null = null
    private remarkableBridge: RemarkableBridge | null = null
    private storage: StorageService | null = null
    private readonly projectState: ProjectState
    private readonly saveStateService: SaveStateService
    private persistenceSnapshot: DataPersistenceSnapshot = { hasPendingFileCommit: false, hasPendingPush: false, isSaving: false }

    constructor() {
        super()
        this.saveStateService = new SaveStateService()
        this.saveStateService.addEventListener('changed', () => this.dispatchPersistenceChanged())
        this.projectState = new ProjectState(
            (cards) => this.agents.attachAgentConversations(cards),
            (previousCards, nextCards) => this.dispatchCardChanges(previousCards, nextCards),
            reportCardParseErrors,
        )
        this.cards = new CardOperations(
            this.createCardOperationsDependencies(),
            (cardPath, state) => {
                this.agents.triggerStateActions(cardPath, state)
                const snapshot = this.projectState.snapshot
                const card = [...(snapshot?.activeCards ?? []), ...(snapshot?.backgroundCards ?? [])]
                    .find(({ path }) => path === cardPath)
                void notifyActionCardStateChange(card?.header.internalId ?? null, state).catch((error: unknown) => {
                    dialogService.error(error, { fallbackMessage: 'Could not update automatic agent finish' })
                })
            },
        )
        this.agents = new AgentIntegration(
            this.createAgentIntegrationDependencies(),
            (cardPath, reference) => this.cards.addAgentLogReference(cardPath, reference),
        )
        agentAcknowledgementService.connectConversationStore((conversation) => this.agents.findStoredConversation(conversation))
        this.projectLoading = new ProjectLoading(
            this.createProjectLoadingDependencies(),
            (snapshot, project, projectLoadToken) => this.agents.loadAgentConversationsInBackground(snapshot, project, projectLoadToken),
        )
        this.releases = new ReleaseOperations(this.createReleaseOperationsDependencies(), () => this.cards.flushPendingCommits())
        agentConversationService.subscribe(() => this.dispatchChanged())
        register('dataService', this)
    }

    init(dependencies: DataServiceDependencies) {
        this.projectLoading.reset()
        this.agents.reset()
        this.projectState.resetLoadedProject()
        this.remarkableBridge = dependencies.remarkableBridge ?? null
        this.storage = withSaveStateTracking(dependencies.storage, this.saveStateService)
        mergeConflictService.init({
            completeBranchCleanup: (cardInternalId) => {
                const snapshot = this.projectState.snapshot
                const card = [...(snapshot?.activeCards ?? []), ...(snapshot?.backgroundCards ?? [])]
                    .find((candidate) => candidate.header.internalId === cardInternalId)
                if (!card) return
                this.cards.updateCardWorktree(card.path, null)
                this.cards.clearCardBranch(card.path)
            },
            reloadPaths: (paths) => this.projectLoading.reloadConflictPaths(paths),
            storage: this.storage,
        })
        worktreeService.init({
            assignCardWorktree: (path, worktree, branch) => this.cards.assignCardWorktree(path, worktree, branch),
            cardSeparatorProvider: () => this.requireDependencies().config.cardSeparator,
            clearCardBranch: (path) => this.cards.clearCardBranch(path),
            flushPendingChanges: flushAggregatePendingChanges,
            projectFolderProvider: () => this.requireDependencies().config.projectFolder,
            projectProvider: () => this.projectState.project,
            snapshotProvider: () => this.projectState.snapshot,
            storageProvider: () => this.storage,
            unassignCardWorktree: (path) => this.cards.updateCardWorktree(path, null),
        })
        this.agents.startScheduledRunWatch()
        const delayMs = configService.get('react.autoCommitDelayMs')
        this.commitBatcher = new CommitBatcher(this.cards, delayMs)
        this.commitBatcher.addEventListener(
            COMMIT_BATCHER_FLUSH_FAILED_EVENT,
            (event) => this.reportCommitFlushFailure((event as CustomEvent<unknown>).detail),
        )
        this.commitBatcher.addEventListener(
            COMMIT_BATCHER_PENDING_CHANGED_EVENT,
            () => this.dispatchPersistenceChanged(),
        )
        this.dispatchChanged()
        this.dispatchPersistenceChanged()
    }

    getState(): DataServiceState {
        return {
            project: this.projectState.project,
            runningAgents: agentConversationService.getRunningAgents(),
            snapshot: this.projectState.snapshot,
        }
    }

    getPersistenceSnapshot(): DataPersistenceSnapshot {
        const currentProject = this.projectState.project

        return {
            hasPendingFileCommit: this.commitBatcher?.hasPending() ?? false,
            hasPendingPush: currentProject ? this.storage?.hasPendingPush?.(currentProject) ?? false : false,
            isSaving: this.saveStateService.getState().isSaving,
        }
    }

    getConfig(): ProjectConfig | null {
        return getProjectConfigOrNull(this.storage)
    }
    async listAgentConversations(context: ActionContext) {
        if (context.kind === 'project') return this.agents.listProjectAgentConversations()
        if (!context.cardInternalId) throw new Error(`Missing cardInternalId for ${context.kind} agent conversation context`)

        return this.agents.ensureAgentConversationsForCard(context.cardInternalId)
    }
    async loadAgentConversation(path: string) {
        const { storage } = this.requireDependencies()
        const currentProject = this.projectState.project
        if (!currentProject) throw new Error('Cannot load an agent conversation before a project is open')

        return loadAgentConversation(storage, currentProject, path)
    }
    async persistActionFile(
        file: MarkdownFile,
        sourcePath = file.path,
        onPathCommitted?: (fromPath: string, toPath: string) => void,
        sourceExists = true,
        saveReference?: OpenDocumentSaveReference,
        onPersisted?: () => void,
    ) {
        const { commitBatcher } = this.requireDependencies()
        const currentProject = this.projectState.project
        if (!currentProject) throw new Error('Cannot save an action before a project is open')

        if (sourceExists && sourcePath === file.path) {
            commitBatcher.schedule(currentProject.branch, [{ ...file, onPersisted, saveReference }], `Update ${file.path}`)
        } else {
            if (!onPathCommitted) throw new Error(`Missing action path callback for rename from ${sourcePath} to ${file.path}`)
            commitBatcher.schedulePathChange(
                currentProject.branch,
                sourcePath,
                { ...file, onPersisted, saveReference },
                `Rename ${sourcePath} to ${file.path}`,
                onPathCommitted,
                sourceExists,
            )
        }
    }

    discardPendingFile(path: string) {
        const { commitBatcher } = this.requireDependencies()
        commitBatcher.discardPendingFile(path)
    }

    hasPendingFile(path: string) {
        const { commitBatcher } = this.requireDependencies()

        return commitBatcher.hasPendingFile(path)
    }

    getRemarkableMetadataContent(): string | null {
        const config = this.getConfig()
        if (!config) return null
        return getRemarkableMetadataContent(this.projectState.files, config)
    }
    async importRemarkableImages(request: RemarkableImportInput): Promise<RemarkableImportPlan> {
        const { config, storage } = this.requireDependencies()
        const currentProject = this.projectState.project
        if (!currentProject) throw new Error('Cannot import Remarkable images before a project is open')
        const plan = await importRemarkableImages({
            bridge: this.remarkableBridge,
            commitAndMergeFiles: (commitRequest, fallbackFiles) => this.cards.commitAndMergeFiles(commitRequest, fallbackFiles),
            config,
            files: this.projectState.files,
            project: currentProject,
            request,
            storage,
        })
        this.refreshSnapshot(config.workingFolder)
        telemetryService.trackEvent('remarkable_import')
        return plan
    }
    private createCardOperationsDependencies(): CardOperationsDeps {
        return {
            cardPathChanged: (fromPath, toPath) => this.dispatchCardPathChanged(fromPath, toPath),
            dispatchChanged: () => this.dispatchChanged(),
            dispatchPersistenceChanged: () => this.dispatchPersistenceChanged(),
            commitPathsInFlight: () => this.projectState.commitPathsInFlight,
            deleteFile: (path, committedFiles, workingFolder) => (
                this.projectState.deleteFile(path, committedFiles, workingFolder)
            ),
            files: () => this.projectState.files,
            mergeCommittedFiles: (files, workingFolder) => this.projectState.mergeCommittedFiles(files, workingFolder),
            mutateCard: (path, mutation, workingFolder) => this.projectState.mutateCard(path, mutation, workingFolder),
            project: () => this.projectState.project,
            recordCommittedContent: (files) => this.projectState.recordCommittedContent(files),
            refreshSnapshot: (workingFolder) => this.refreshSnapshot(workingFolder),
            reloadCurrentProjectSnapshot: () => this.projectLoading.reloadCurrentProjectSnapshot(),
            renameFile: (fromPath, toPath, workingFolder) => this.projectState.renameFile(fromPath, toPath, workingFolder),
            requireDependencies: () => this.requireDependencies(),
            requireCard: (path) => this.projectState.requireCard(path),
            requireCardByInternalId: (internalId) => this.projectState.requireCardByInternalId(internalId),
            requireFile: (path) => this.projectState.requireFile(path),
            replaceFiles: (files, workingFolder) => this.projectState.replaceFiles(files, workingFolder),
            snapshot: () => this.projectState.snapshot,
        }
    }

    private createAgentIntegrationDependencies(): AgentIntegrationDeps {
        return {
            beginAgentConversationLoad: () => this.projectState.beginAgentConversationLoad(),
            isCurrentAgentConversationLoad: (agentConversationLoadToken) => (
                this.projectState.isCurrentAgentConversationLoad(agentConversationLoadToken)
            ),
            isCurrentLoad: (project, projectLoadToken) => this.projectState.isCurrentLoad(project, projectLoadToken),
            project: () => this.projectState.project,
            refreshSnapshot: (workingFolder) => this.refreshSnapshot(workingFolder),
            requireDependencies: () => this.requireDependencies(),
            requireFile: (path) => this.projectState.requireFile(path),
            snapshot: () => this.projectState.snapshot,
            conversationChanged: (cardPath) => this.dispatchEvent(new Event(cardFieldChangedEvent(cardPath, 'conversation'))),
        }
    }

    private createProjectLoadingDependencies(): ProjectLoadingDeps {
        return {
            beginProjectLoad: () => this.projectState.beginProjectLoad(),
            clearLoadedProject: () => this.projectState.resetLoadedProject(),
            commitPathsInFlight: () => this.projectState.commitPathsInFlight,
            dispatchChanged: () => this.dispatchChanged(),
            dispatchPersistenceChanged: () => this.dispatchPersistenceChanged(),
            dispatchRepositoryChanged: (event) => this.dispatchEvent(new CustomEvent('repositoryChanged', { detail: event })),
            files: () => this.projectState.files,
            flushPendingChanges: flushAggregatePendingChanges,
            isCommittedContent: (path, content) => this.projectState.isCommittedContent(path, content),
            isCurrentLoad: (project, projectLoadToken) => this.projectState.isCurrentLoad(project, projectLoadToken),
            mergeBackgroundProjectFiles: (files, workingFolder, repositoryFiles) => (
                this.projectState.mergeBackgroundProjectFiles(files, workingFolder, repositoryFiles)
            ),
            project: () => this.projectState.project,
            replaceFiles: (files, workingFolder) => this.projectState.replaceFiles(files, workingFolder),
            replaceProject: (project) => this.projectState.replaceProject(project),
            ensureCardInternalIds: async () => {
                if (this.cards.ensureCardInternalIds() > 0) await this.cards.flushPendingCommits()
            },
            replaceProjectFiles: (files, workingFolder, repositoryFiles) => (
                this.projectState.replaceProjectFiles(files, workingFolder, repositoryFiles)
            ),
            requireDependencies: () => this.requireDependencies(),
            resetAgentConversations: () => this.agents.resetLoadedConversations(),
            snapshot: () => this.projectState.snapshot,
            storage: () => this.storage,
        }
    }

    private createReleaseOperationsDependencies(): ReleaseOperationsDeps {
        return {
            files: () => this.projectState.files,
            project: () => this.projectState.project,
            reloadCurrentProjectSnapshot: () => this.projectLoading.reloadCurrentProjectSnapshot(),
            requireDependencies: () => this.requireDependencies(),
            snapshot: () => this.projectState.snapshot,
        }
    }

    private refreshSnapshot(workingFolder: string) {
        this.projectState.refreshSnapshot(workingFolder)
        this.dispatchChanged()
    }
    private reportCommitFlushFailure(error: unknown) {
        reportCommitFlushFailure(error, () => this.dispatchPersistenceChanged())
    }
    private requireDependencies() {
        if (!this.storage) throw new Error('Data service storage is not initialized')
        if (!this.commitBatcher) throw new Error('Data service commit batcher is not initialized')
        const config = resolveProjectConfigPaths(configService.getProjectConfig())
        return { commitBatcher: this.commitBatcher, config, storage: this.storage }
    }
    private dispatchChanged() {
        this.dispatchPersistenceChanged()
        this.dispatchEvent(new CustomEvent<DataServiceState>('changed', { detail: this.getState() }))
    }
    private dispatchCardPathChanged(fromPath: string, toPath: string) {
        const detail: CardPathChangedEventDetail = { fromPath, toPath }
        this.dispatchEvent(new CustomEvent<CardPathChangedEventDetail>(CARD_PATH_CHANGED_EVENT, { detail }))
    }
    private dispatchCardChanges(
        previousCards: ProjectSnapshot['activeCards'],
        nextCards: ProjectSnapshot['activeCards'],
    ) {
        const previousByPath = new Map(previousCards.map((card) => [card.path, card]))
        const nextByPath = new Map(nextCards.map((card) => [card.path, card]))
        for (const card of previousCards) {
            if (!nextByPath.has(card.path)) {
                this.dispatchEvent(new CustomEvent<CardRemovedEventDetail>(CARD_REMOVED_EVENT, { detail: { card: eventCard(card) } }))
            }
        }
        for (const card of nextCards) {
            const previousCard = previousByPath.get(card.path)
            if (!previousCard) {
                this.dispatchEvent(new CustomEvent<CardAddedEventDetail>(CARD_ADDED_EVENT, { detail: { card: eventCard(card) } }))
            } else if (previousCard !== card) {
                const detail = { card: eventCard(card), previousCard: eventCard(previousCard) }
                this.dispatchEvent(new CustomEvent<CardChangedEventDetail>(CARD_CHANGED_EVENT, { detail }))
                for (const field of CARD_FIELDS) {
                    if (!cardFieldChanged(field, previousCard, card)) continue
                    this.dispatchEvent(new Event(cardFieldChangedEvent(card.path, field)))
                    this.dispatchEvent(new Event(cardCollectionFieldChangedEvent(field)))
                }
                if (previousCard.header.status !== card.header.status && card.header.status) {
                    const finishNotification = notifyActionCardStateChange(card.header.internalId, card.header.status)
                    void finishNotification.catch((error: unknown) => {
                        dialogService.error(error, { fallbackMessage: 'Could not update automatic agent finish' })
                    })
                }
            }
        }
    }
    private dispatchPersistenceChanged() {
        const nextSnapshot = this.getPersistenceSnapshot()
        if (DataService.isSamePersistenceSnapshot(this.persistenceSnapshot, nextSnapshot)) return

        this.persistenceSnapshot = nextSnapshot
        this.dispatchEvent(new CustomEvent<DataPersistenceSnapshot>('persistenceChanged', { detail: nextSnapshot }))
    }
    private static isSamePersistenceSnapshot(first: DataPersistenceSnapshot, second: DataPersistenceSnapshot) {
        return first.hasPendingFileCommit === second.hasPendingFileCommit
            && first.hasPendingPush === second.hasPendingPush
            && first.isSaving === second.isSaving
    }
}

export const dataService = new DataService()

