import { ACTION_SCHEDULES_FILE } from '../../data/action_schedule_types'
import { deriveStatesFromCards, mergeStatesWithDefaults } from '../../data/card_ordering'
import type { CardSeparator } from '../../data/card_identifiers'
import { resolveProjectConfigPaths, type MarkdownFile, type ProjectAsset, type ProjectConfig, type ProjectReference, type ProjectSnapshot, type ProjectWatchEvent, type StorageService } from '../../data/data_types'
import { actionService, type ActionReloadChange } from '../actions/action_service'
import { configService } from '../config/config_service'
import {
    type RequiredDataServiceDependencies,
    errorMessage,
    mergeFiles,
    removeFilesByPath,
    reportWorkspaceError,
    reportWorkspaceNotice,
} from '../data/data_service_context'
import { planExternalCardImports, type ExternalCardImportPlan } from '../data/external_card_import_service'
import { telemetryService } from '../telemetry/telemetry_service'
import { createRandomProjectBackgroundShade } from '../../theme/project_background_shade'
import { worktreeService } from './worktree_service'
import { planCardSeparatorMigration } from '../data/card_separator_migration'
import { globalProgressService } from '../global_progress_service'
import { dialogService } from '../dialog_service'
import { GithubUnauthorizedError } from '../../auth/github_api_client'
import { createDefaultActionFiles } from '../../project_template/project_template'
import { openFilesService } from '../open_files_service'
import { mergeConflictService } from './merge_conflict_service'

const ACTION_RELOAD_DEBOUNCE_MS = 150
const JSON_EXTENSION = '.json'
const MARKDOWN_EXTENSION = '.md'
const PROJECT_CONFIG_PATH = 'md2.config.json'
// The watcher already settles each path before reporting, so this only has to group
// events for different files into a single snapshot rebuild.
const MARKDOWN_RELOAD_DEBOUNCE_MS = 50
const MARKDOWN_REMOVAL_GRACE_MS = 750
const PROJECT_LOAD_ERROR_REPORTED = Symbol('project-load-error-reported')

type ReportedProjectLoadError = object & { [PROJECT_LOAD_ERROR_REPORTED]?: boolean }

interface ExternalCardImportResult {
    files: MarkdownFile[]
    importedFiles: MarkdownFile[]
    sourcePaths: string[]
    succeeded: boolean
}

interface ExternalCardImportInProgress {
    project: ProjectReference
    promise: Promise<ExternalCardImportResult>
}

export function isProjectLoadErrorReported(error: unknown) {
    return typeof error === 'object' && error !== null && !!(error as ReportedProjectLoadError)[PROJECT_LOAD_ERROR_REPORTED]
}

function markProjectLoadErrorReported(error: unknown) {
    if (typeof error === 'object' && error !== null) (error as ReportedProjectLoadError)[PROJECT_LOAD_ERROR_REPORTED] = true
}

function importedNoticeMessage(count: number) {
    return `Imported ${count} external ${count === 1 ? 'file' : 'files'} as new cards.`
}

function isActionDefinitionPath(path: string, actionsFolder: string) {
    const normalizedPath = path.replace(/\\/gu, '/')
    const normalizedActionsFolder = actionsFolder.replace(/\\/gu, '/').replace(/\/$/u, '')
    const fileName = normalizedPath.split('/').pop()
    if (fileName === ACTION_SCHEDULES_FILE) return false

    return normalizedPath.startsWith(`${normalizedActionsFolder}/`) && normalizedPath.toLowerCase().endsWith(JSON_EXTENSION)
}

function isProjectMarkdownPath(path: string, projectFolder: string) {
    const normalizedPath = path.replace(/\\/gu, '/')
    const normalizedProjectFolder = projectFolder.replace(/\\/gu, '/').replace(/\/$/u, '')
    if (normalizedProjectFolder.length === 0) return normalizedPath.toLowerCase().endsWith(MARKDOWN_EXTENSION)

    return normalizedPath.startsWith(`${normalizedProjectFolder}/`) && normalizedPath.toLowerCase().endsWith(MARKDOWN_EXTENSION)
}

function reportMarkdownWatchConflict(path: string) {
    reportWorkspaceError(`External change ignored for ${path} because the file has unsaved local edits.`)
}

function reportActionLoadIssues() {
    const message = actionService.getState().error
    if (message) dialogService.warning(message, { title: 'Some actions were not loaded' })
}

function backgroundProjectLoadFailureMessage(error: unknown) {
    const detail = errorMessage(error, 'Unknown error')

    return `Background project data failed to load - search and history may be incomplete. ${detail}`
}

function reportOptionalProjectLoadFailure(area: string, error: unknown) {
    const detail = errorMessage(error, 'Unknown error')
    dialogService.warning(`${area} could not be loaded and was skipped. ${detail}`, { title: 'Project loaded with errors' })
    telemetryService.captureError(error)
}

function initializeMissingProjectStates(projectConfig: Partial<ProjectConfig> | null, snapshot: ProjectSnapshot) {
    if (projectConfig?.states !== undefined) return

    const derivedStates = deriveStatesFromCards(snapshot.activeCards)
    configService.set('project.states', mergeStatesWithDefaults(derivedStates))
}

export interface ProjectLoadingDeps {
    beginProjectLoad(): number
    clearLoadedProject(): void
    commitPathsInFlight(): Set<string>
    dispatchChanged(): void
    dispatchPersistenceChanged(): void
    dispatchRepositoryChanged(event: ProjectWatchEvent): void
    ensureCardInternalIds(): Promise<void>
    files(): MarkdownFile[]
    flushPendingChanges(): Promise<void>
    isCommittedContent(path: string, content: string): boolean
    isCurrentLoad(project: ProjectReference, projectLoadToken: number): boolean
    mergeBackgroundProjectFiles(files: MarkdownFile[], workingFolder: string, repositoryFiles: string[]): void
    project(): ProjectReference | null
    replaceFiles(files: MarkdownFile[], workingFolder: string): void
    replaceProject(project: ProjectReference | null): void
    replaceProjectFiles(files: MarkdownFile[], workingFolder: string, repositoryFiles: string[]): void
    requireDependencies(): RequiredDataServiceDependencies
    resetAgentConversations(): void
    snapshot(): ProjectSnapshot | null
    storage(): StorageService | null
}

export class ProjectLoading {
    private readonly dependencies: ProjectLoadingDeps
    private readonly loadAgentConversationsInBackground: (
        snapshot: ProjectSnapshot,
        project: ProjectReference,
        projectLoadToken: number,
    ) => void
    private actionReloadChangesByPath: Map<string, ActionReloadChange> = new Map()
    private actionReloadTimeout: number | null = null
    private markdownReloadEventsByPath: Map<string, ProjectWatchEvent> = new Map()
    private markdownRemovalTimeoutsByPath: Map<string, number> = new Map()
    private markdownReloadTimeout: number | null = null
    private externalCardImportInProgress: ExternalCardImportInProgress | null = null
    private watchCleanup: (() => void) | null = null

    constructor(
        dependencies: ProjectLoadingDeps,
        loadAgentConversationsInBackground: (
            snapshot: ProjectSnapshot,
            project: ProjectReference,
            projectLoadToken: number,
        ) => void,
    ) {
        this.dependencies = dependencies
        this.loadAgentConversationsInBackground = loadAgentConversationsInBackground
    }

    reset() {
        this.stopProjectWatch()
        this.clearActionReloadTimeout()
        this.clearMarkdownReloadTimeout()
        this.clearMarkdownRemovalTimeouts()
        this.actionReloadChangesByPath.clear()
        this.markdownReloadEventsByPath = new Map()
        this.dependencies.beginProjectLoad()
    }

    async createProject(project: ProjectReference) {
        const { config, storage } = this.dependencies.requireDependencies()
        const rawConfig = { ...configService.getProjectConfig(), backgroundShade: createRandomProjectBackgroundShade() }
        this.dependencies.replaceProject(await storage.createProject(project, config.workingFolder))
        const currentProject = this.dependencies.project()
        if (!currentProject) throw new Error('Cannot create a project without a project reference')

        await storage.commit({
            branch: currentProject.branch,
            files: createDefaultActionFiles(config.actionsFolder),
            message: 'Add default MDÂ² actions',
        })
        await storage.saveProjectConfig(currentProject, rawConfig)
        telemetryService.trackEvent('create_project')

        return this.openProject(currentProject)
    }

    async openProject(project: ProjectReference) {
        const { storage } = this.dependencies.requireDependencies()
        await this.dependencies.flushPendingChanges()
        this.clearMarkdownReloadTimeout()
        this.clearMarkdownRemovalTimeouts()
        const projectLoadToken = this.dependencies.beginProjectLoad()
        this.dependencies.resetAgentConversations()
        this.actionReloadChangesByPath.clear()
        this.markdownReloadEventsByPath = new Map()
        this.dependencies.replaceProject(project)

        try {
            const projectConfig = await this.loadProjectConfig(project)
            if (projectConfig === null) await this.saveMissingProjectConfig(project)

            const config = resolveProjectConfigPaths(configService.getProjectConfig())
            if (config.pushMode === 'manual') {
                await storage.restorePendingCommits?.(project)
                await this.loadPendingPush(project)
            }

            await this.loadActions(project, config.actionsFolder)
            const projectFiles = await storage.loadProjectRoot(project, config.workingFolder)
            const repositoryFiles: string[] = []
            this.dependencies.replaceProjectFiles(projectFiles.files, config.workingFolder, repositoryFiles)
            await this.dependencies.ensureCardInternalIds()
            this.tryStartProjectWatch()
            const currentSnapshot = this.dependencies.snapshot()
            if (!currentSnapshot) throw new Error('Project snapshot was not created')
            initializeMissingProjectStates(projectConfig ?? null, currentSnapshot)
            this.dependencies.dispatchChanged()
            reportActionLoadIssues()

            this.loadAgentConversationsInBackground(currentSnapshot, project, projectLoadToken)
            void this.loadFullProjectInBackground(project, config.projectFolder, config.workingFolder, projectLoadToken)
            telemetryService.trackEvent('open_project')

            return currentSnapshot
        } catch (error) {
            this.clearFailedProjectLoad()
            dialogService.error(error, { fallbackMessage: 'Project could not be loaded', title: 'Project load failed' })
            telemetryService.captureError(error)
            markProjectLoadErrorReported(error)
            throw error
        }
    }

    async saveProjectConfig() {
        const { storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) throw new Error('Cannot save project config before a project is open')

        await storage.saveProjectConfig(currentProject, configService.getProjectConfig())
        this.dependencies.dispatchPersistenceChanged()
    }

    async updateCardSeparator(previousSeparator: CardSeparator, nextSeparator: CardSeparator) {
        if (previousSeparator === nextSeparator) return 0

        const { config, storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) throw new Error('Cannot rename card files before a project is open')

        await this.dependencies.flushPendingChanges()
        const projectFiles = await storage.loadProject(currentProject, config.projectFolder)
        const moves = planCardSeparatorMigration(projectFiles.files, previousSeparator, nextSeparator)
        if (moves.length === 0) return 0

        globalProgressService.start('Preparing card file names', moves.length)
        try {
            for (const [index, move] of moves.entries()) {
                globalProgressService.update(index, `Renaming ${move.fromPath}`)
                const inFlightCommitPaths = this.dependencies.commitPathsInFlight()
                inFlightCommitPaths.add(move.fromPath)
                inFlightCommitPaths.add(move.toPath)
                try {
                    await storage.moveFiles({
                        branch: currentProject.branch,
                        message: `Rename card file ${index + 1} of ${moves.length}`,
                        moves: [move],
                    })
                } finally {
                    inFlightCommitPaths.delete(move.fromPath)
                    inFlightCommitPaths.delete(move.toPath)
                }
                globalProgressService.update(index + 1, `Renamed ${move.toPath}`)
            }

            if (config.pushMode === 'auto') await storage.push(currentProject)
            await this.reloadCurrentProjectSnapshot()

            return moves.length
        } finally {
            globalProgressService.finish()
        }
    }

    async loadProjectAsset(path: string): Promise<ProjectAsset> {
        const { storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) throw new Error('Cannot load a project asset before a project is open')
        if (!storage.loadProjectAsset) throw new Error('Project asset loading is not available')

        return storage.loadProjectAsset(currentProject, path)
    }

    async switchBranch(branch: string) {
        const { storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) throw new Error('Cannot switch branch before a project is open')

        await this.dependencies.flushPendingChanges()
        const project = await storage.checkoutBranch(currentProject, branch)

        return this.openProject(project)
    }

    async push() {
        const { storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) throw new Error('Cannot push before a project is open')

        await storage.push(currentProject)
        this.dependencies.dispatchPersistenceChanged()
    }

    async pull() {
        const { storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) throw new Error('Cannot pull before a project is open')
        if (!storage.pull) throw new Error('Pulling the primary worktree is not available')

        await storage.pull(currentProject)
    }

    async reloadCurrentProjectSnapshot() {
        const { config, storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) throw new Error('Cannot reload project snapshot before a project is open')

        const project = currentProject
        const projectLoadToken = this.dependencies.beginProjectLoad()
        const projectFiles = await storage.loadProject(currentProject, config.projectFolder)
        const repositoryFiles = await storage.listRepositoryFiles(currentProject)
        this.dependencies.replaceProjectFiles(projectFiles.files, config.workingFolder, repositoryFiles)
        await this.dependencies.ensureCardInternalIds()
        this.dependencies.dispatchChanged()
        const currentSnapshot = this.dependencies.snapshot()
        if (currentSnapshot) this.loadAgentConversationsInBackground(currentSnapshot, project, projectLoadToken)

        return currentSnapshot
    }

    stopProjectWatch() {
        if (!this.watchCleanup) return

        this.watchCleanup()
        this.watchCleanup = null
    }

    async reloadConflictPaths(paths: string[]) {
        const { config } = this.dependencies.requireDependencies()
        for (const path of paths) {
            if (!isProjectMarkdownPath(path, config.projectFolder)) continue
            this.markdownReloadEventsByPath.set(path, { changeKind: 'unknown', path })
        }
        if (this.markdownReloadEventsByPath.size === 0) return

        await this.reloadMarkdownFilesFromWatchEvents()
    }

    private clearFailedProjectLoad() {
        this.stopProjectWatch()
        this.clearActionReloadTimeout()
        this.clearMarkdownReloadTimeout()
        this.clearMarkdownRemovalTimeouts()
        this.dependencies.beginProjectLoad()
        this.dependencies.resetAgentConversations()
        this.dependencies.clearLoadedProject()
        this.actionReloadChangesByPath.clear()
        this.markdownReloadEventsByPath.clear()
        actionService.clear()
        worktreeService.clear()
        this.dependencies.dispatchChanged()
    }

    private async loadProjectConfig(project: ProjectReference) {
        const { storage } = this.dependencies.requireDependencies()

        try {
            const projectConfig = await storage.loadProjectConfig(project)
            configService.loadProjectConfig(projectConfig)

            return projectConfig
        } catch (error) {
            if (error instanceof GithubUnauthorizedError) throw error

            configService.loadProjectConfig(null)
            reportOptionalProjectLoadFailure('Project configuration', error)

            return undefined
        }
    }

    private async saveMissingProjectConfig(project: ProjectReference) {
        const { storage } = this.dependencies.requireDependencies()
        configService.set('project.backgroundShade', createRandomProjectBackgroundShade())

        try {
            await storage.saveProjectConfig(project, configService.getProjectConfig())
        } catch (error) {
            reportOptionalProjectLoadFailure('Generated project configuration', error)
        }
    }

    private async loadActions(project: ProjectReference, actionsFolder: string) {
        const { storage } = this.dependencies.requireDependencies()

        try {
            const actionFiles = await storage.loadActionFiles(project, actionsFolder)
            actionService.loadFromFiles(actionFiles)
        } catch (error) {
            actionService.clear()
            reportOptionalProjectLoadFailure('Actions', error)
        }
    }

    private async loadPendingPush(project: ProjectReference) {
        const { storage } = this.dependencies.requireDependencies()

        try {
            await storage.loadPendingPush?.(project)
        } catch (error) {
            reportOptionalProjectLoadFailure('Pending push state', error)
        }
    }

    private tryStartProjectWatch() {
        try {
            this.startProjectWatch()
        } catch (error) {
            reportOptionalProjectLoadFailure('Project file watching', error)
        }
    }

    private async importExternalCardFiles(files: MarkdownFile[], workingFolder: string) {
        const currentProject = this.dependencies.project()
        if (!currentProject) return files

        let nextFiles = files
        while (this.externalCardImportInProgress) {
            const activeImport = this.externalCardImportInProgress
            const result = await activeImport.promise
            const isSameProject = activeImport.project.id === currentProject.id
                && activeImport.project.branch === currentProject.branch
            if (isSameProject) {
                if (!result.succeeded) return nextFiles
                nextFiles = mergeFiles(removeFilesByPath(nextFiles, result.sourcePaths), result.importedFiles)
            }
            if (this.externalCardImportInProgress === activeImport) this.externalCardImportInProgress = null
        }

        const activeProject = this.dependencies.project()
        if (activeProject?.id !== currentProject.id || activeProject.branch !== currentProject.branch) return nextFiles

        const { config } = this.dependencies.requireDependencies()
        const plan = planExternalCardImports(nextFiles, workingFolder, config.cardSeparator, config.cardTypes, config.states[0].state)
        if (plan.moves.length === 0) return nextFiles

        const promise = this.executeExternalCardImport(nextFiles, currentProject, plan)
        const activeImport = { project: currentProject, promise }
        this.externalCardImportInProgress = activeImport

        try {
            const result = await promise

            return result.files
        } finally {
            if (this.externalCardImportInProgress === activeImport) this.externalCardImportInProgress = null
        }
    }

    private async executeExternalCardImport(
        files: MarkdownFile[],
        currentProject: ProjectReference,
        plan: ExternalCardImportPlan,
    ): Promise<ExternalCardImportResult> {
        const { config, storage } = this.dependencies.requireDependencies()

        const importPaths = plan.moves.flatMap((move) => [move.fromPath, move.toPath])
        const sourcePaths = plan.moves.map((move) => move.fromPath)
        const inFlightCommitPaths = this.dependencies.commitPathsInFlight()
        importPaths.forEach((path) => inFlightCommitPaths.add(path))

        try {
            await storage.moveFiles({
                branch: currentProject.branch,
                message: `Import ${plan.moves.length} external ${plan.moves.length === 1 ? 'file' : 'files'}`,
                moves: plan.moves,
            })
        } catch (error) {
            reportWorkspaceError(errorMessage(error, 'External file import failed'))
            telemetryService.captureError(error)

            return { files, importedFiles: [], sourcePaths: [], succeeded: false }
        } finally {
            importPaths.forEach((path) => inFlightCommitPaths.delete(path))
        }

        if (config.pushMode === 'auto') await storage.push(currentProject)
        if (config.pushMode === 'manual') this.dependencies.dispatchPersistenceChanged()

        reportWorkspaceNotice(importedNoticeMessage(plan.moves.length))
        telemetryService.trackEvent('external_file_import')

        const importedFiles = mergeFiles(removeFilesByPath(files, sourcePaths), plan.importedFiles)

        return { files: importedFiles, importedFiles: plan.importedFiles, sourcePaths, succeeded: true }
    }

    private async loadFullProjectInBackground(
        project: ProjectReference,
        projectFolder: string,
        workingFolder: string,
        projectLoadToken: number,
    ) {
        const { storage } = this.dependencies.requireDependencies()
        const [projectFilesResult, repositoryFilesResult] = await Promise.allSettled([
            storage.loadProject(project, projectFolder),
            storage.listRepositoryFiles(project),
        ])
        if (!this.shouldApplyProjectLoad(project, projectLoadToken)) return

        let nextFiles = this.dependencies.files()
        let projectFilesLoaded = false
        if (projectFilesResult.status === 'fulfilled') {
            try {
                const importedFiles = await this.importExternalCardFiles(projectFilesResult.value.files, workingFolder)
                if (!this.shouldApplyProjectLoad(project, projectLoadToken)) return

                const importedPaths = new Set(importedFiles.map((file) => file.path))
                const removedImportedPaths = projectFilesResult.value.files
                    .filter((file) => !importedPaths.has(file.path))
                    .map((file) => file.path)
                const remainingFiles = removeFilesByPath(this.dependencies.files(), removedImportedPaths)
                nextFiles = mergeFiles(importedFiles, remainingFiles)
                projectFilesLoaded = true
            } catch (error) {
                reportWorkspaceError(backgroundProjectLoadFailureMessage(error))
                telemetryService.captureError(error)
            }
        } else {
            reportWorkspaceError(backgroundProjectLoadFailureMessage(projectFilesResult.reason))
            telemetryService.captureError(projectFilesResult.reason)
        }

        const currentRepositoryFiles = this.dependencies.snapshot()?.repositoryFiles ?? []
        const repositoryFiles = repositoryFilesResult.status === 'fulfilled'
            ? repositoryFilesResult.value
            : currentRepositoryFiles
        if (repositoryFilesResult.status === 'rejected') {
            reportOptionalProjectLoadFailure('Repository file index', repositoryFilesResult.reason)
        }
        if (!projectFilesLoaded && repositoryFilesResult.status === 'rejected') return
        if (!this.shouldApplyProjectLoad(project, projectLoadToken)) return

        this.dependencies.mergeBackgroundProjectFiles(nextFiles, workingFolder, repositoryFiles)
        await this.dependencies.ensureCardInternalIds()
        this.dependencies.dispatchChanged()
        const currentSnapshot = this.dependencies.snapshot()
        if (currentSnapshot) this.loadAgentConversationsInBackground(currentSnapshot, project, projectLoadToken)
    }

    private shouldApplyProjectLoad(project: ProjectReference, projectLoadToken: number) {
        return this.dependencies.isCurrentLoad(project, projectLoadToken)
    }

    private startProjectWatch() {
        this.stopProjectWatch()
        const currentProject = this.dependencies.project()
        const storage = this.dependencies.storage()
        if (!currentProject || !storage?.watchProject) return

        this.watchCleanup = storage.watchProject(
            currentProject,
            (event) => this.handleProjectWatchEvent(event),
            () => void this.resynchronizeProjectAfterWatchRestore(),
        )
    }

    private async resynchronizeProjectAfterWatchRestore() {
        const { config, storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) return

        try {
            const projectFiles = await storage.loadProject(currentProject, config.projectFolder)
            if (this.dependencies.project() !== currentProject) return

            const currentFiles = this.dependencies.files().filter((file) => isProjectMarkdownPath(file.path, config.projectFolder))
            const currentFilesByPath = new Map(currentFiles.map((file) => [file.path, file]))
            const loadedPaths = new Set<string>()
            for (const file of projectFiles.files) {
                if (!isProjectMarkdownPath(file.path, config.projectFolder)) continue

                loadedPaths.add(file.path)
                const currentFile = currentFilesByPath.get(file.path)
                if (currentFile?.content === file.content) continue

                this.handleProjectWatchEvent({
                    changeKind: currentFile ? 'changed' : 'added',
                    path: file.path,
                })
            }
            for (const file of currentFiles) {
                if (!loadedPaths.has(file.path)) this.handleProjectWatchEvent({ changeKind: 'removed', path: file.path })
            }
        } catch (error) {
            reportOptionalProjectLoadFailure('Project resynchronization', error)
        }
    }

    private handleProjectWatchEvent(event: ProjectWatchEvent) {
        if (mergeConflictService.isConflictedPath(event.path)) return
        this.dependencies.dispatchRepositoryChanged(event)
        if (event.path === PROJECT_CONFIG_PATH) {
            void this.reloadProjectConfigFromWatch()
            return
        }
        const { config } = this.dependencies.requireDependencies()
        if (isActionDefinitionPath(event.path, config.actionsFolder)) {
            const change: ActionReloadChange = this.dependencies.commitPathsInFlight().has(event.path)
                ? { origin: 'local', path: event.path, revision: actionService.getPublicationRevision(event.path) }
                : { origin: 'external', path: event.path }
            this.scheduleActionReload(change)
            return
        }

        if (!isProjectMarkdownPath(event.path, config.projectFolder)) return
        if (this.dependencies.commitPathsInFlight().has(event.path)) return

        this.scheduleMarkdownReload(event)
    }

    private async reloadProjectConfigFromWatch() {
        const { storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) return

        try {
            configService.loadProjectConfig(await storage.loadProjectConfig(currentProject))
        } catch (error) {
            reportOptionalProjectLoadFailure('Project configuration reload', error)
        }
    }

    private scheduleActionReload(change: ActionReloadChange) {
        this.actionReloadChangesByPath.set(change.path, change)
        this.clearActionReloadTimeout()
        this.actionReloadTimeout = window.setTimeout(() => {
            void this.reloadActionsFromCurrentProject()
        }, ACTION_RELOAD_DEBOUNCE_MS)
    }

    private clearActionReloadTimeout() {
        if (this.actionReloadTimeout === null) return

        window.clearTimeout(this.actionReloadTimeout)
        this.actionReloadTimeout = null
    }

    private scheduleMarkdownReload(event: ProjectWatchEvent) {
        const pendingRemovalTimeout = this.markdownRemovalTimeoutsByPath.get(event.path)
        if (pendingRemovalTimeout !== undefined) {
            window.clearTimeout(pendingRemovalTimeout)
            this.markdownRemovalTimeoutsByPath.delete(event.path)
        }

        if (event.changeKind === 'removed') {
            const timeout = window.setTimeout(() => {
                this.markdownRemovalTimeoutsByPath.delete(event.path)
                this.markdownReloadEventsByPath.set(event.path, event)
                this.scheduleMarkdownReloadBatch()
            }, MARKDOWN_REMOVAL_GRACE_MS)
            this.markdownRemovalTimeoutsByPath.set(event.path, timeout)
            return
        }

        this.markdownReloadEventsByPath.set(event.path, event)
        this.scheduleMarkdownReloadBatch()
    }

    private scheduleMarkdownReloadBatch() {
        this.clearMarkdownReloadTimeout()
        this.markdownReloadTimeout = window.setTimeout(() => {
            void this.reloadMarkdownFilesFromWatchEvents()
        }, MARKDOWN_RELOAD_DEBOUNCE_MS)
    }

    private clearMarkdownReloadTimeout() {
        if (this.markdownReloadTimeout === null) return

        window.clearTimeout(this.markdownReloadTimeout)
        this.markdownReloadTimeout = null
    }

    private clearMarkdownRemovalTimeouts() {
        this.markdownRemovalTimeoutsByPath.forEach((timeout) => window.clearTimeout(timeout))
        this.markdownRemovalTimeoutsByPath.clear()
    }

    private async reloadMarkdownFilesFromWatchEvents() {
        const { commitBatcher, storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject || !storage.loadFile) return

        this.clearMarkdownReloadTimeout()
        const events = [...this.markdownReloadEventsByPath.values()]
        this.markdownReloadEventsByPath.clear()
        const updatedFiles: MarkdownFile[] = []
        const removedPaths: string[] = []

        for (const event of events) {
            if (this.dependencies.commitPathsInFlight().has(event.path)) continue
            const loadedFile = event.changeKind === 'removed' ? null : await this.loadWatchedMarkdownFile(event)
            // The watcher reports our own commits after the in-flight window has closed; the
            // stored commit hash recognizes those echoes so they never count as external edits.
            if (loadedFile && this.dependencies.isCommittedContent(loadedFile.path, loadedFile.content)) continue
            const dirtyOpenDocument = openFilesService.getRegisteredDocuments().some((document) => (
                document.kind === 'card' && document.path === event.path && document.dirty
            ))
            if (commitBatcher.hasPendingFile(event.path) || dirtyOpenDocument) {
                reportMarkdownWatchConflict(event.path)
                continue
            }

            if (event.changeKind === 'removed') {
                removedPaths.push(event.path)
                continue
            }

            if (!loadedFile) {
                if (event.changeKind === 'unknown') removedPaths.push(event.path)
                continue
            }

            const currentFile = this.dependencies.files().find((file) => file.path === loadedFile.path)
            if (currentFile?.content === loadedFile.content) continue

            updatedFiles.push(loadedFile)
        }

        const removedPathSet = new Set(removedPaths)
        const watchedFiles = mergeFiles(
            this.dependencies.files().filter((file) => !removedPathSet.has(file.path)),
            updatedFiles,
        )
        const importedFiles = await this.importExternalCardFiles(watchedFiles, this.dependencies.requireDependencies().config.workingFolder)
        if (updatedFiles.length === 0 && removedPaths.length === 0 && importedFiles === watchedFiles) return

        const repositoryFiles = await storage.listRepositoryFiles(currentProject)
        const { config } = this.dependencies.requireDependencies()
        this.dependencies.replaceProjectFiles(importedFiles, config.workingFolder, repositoryFiles)
        await this.dependencies.ensureCardInternalIds()
        this.dependencies.dispatchChanged()
    }

    private async loadWatchedMarkdownFile(event: ProjectWatchEvent) {
        const { storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject || !storage.loadFile) return null

        try {
            return await storage.loadFile(currentProject, event.path)
        } catch (error) {
            if (event.changeKind === 'unknown' || event.changeKind === 'removed') return null

            console.error('Failed to load watched markdown file', error)

            return null
        }
    }

    private async reloadActionsFromCurrentProject() {
        const { config, storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) return

        const changes = [...this.actionReloadChangesByPath.values()]
        if (changes.length === 0) return

        this.clearActionReloadTimeout()
        this.actionReloadChangesByPath.clear()
        const actionFiles = await storage.loadActionFiles(currentProject, config.actionsFolder)
        actionService.reloadFromFiles(actionFiles, changes)
        reportActionLoadIssues()
    }
}

import { cardContext, fileContext, type ActionContext } from '../../data/action_context'
import { BUILTIN_CUSTOM_PROMPT, type ActionDefinition } from '../../data/action_types'
import type { ActionRunEvent } from '../../data/action_run_types'
import {
    type AgentConversation,
    type AgentConversationError,
    type MarkdownFile,
    type Card,
    type ProjectReference,
    type ProjectSnapshot,
    type StorageService,
} from '../../data/data_types'
import { actionService } from '../actions/action_service'
import { actionRunRegistry } from '../actions/action_run_registry'
import { agentAcknowledgementService } from './agent_acknowledgement_service'
import { listAgentConversationReferences, loadAgentConversation } from './agent_conversation_service'
import { runElectronAction } from '../actions/electron_action_runner'
import { mapWithConcurrency } from '../concurrency'
import { type RequiredDataServiceDependencies } from '../data/data_service_context'
import { telemetryService } from '../telemetry/telemetry_service'
import { dialogService } from '../dialog_service'

const AGENT_CONVERSATION_LOAD_CONCURRENCY = 8
const ON_STATE_ACTION_ERROR_PATH_PREFIX = 'onState'

interface ResolvedAgentConversations {
    conversationsByCardInternalId: Map<string, AgentConversation[]>
    errorsByCardPath: Map<string, AgentConversationError[]>
}

interface AgentConversationLoadTask {
    cardInternalId: string
    cardPath: string
    reference: string
}

type AgentConversationLoadResult =
    | { cardInternalId: string; cardPath: string; conversation: AgentConversation; error: null }
    | { cardInternalId: string; cardPath: string; conversation: null; error: AgentConversationError }

export interface AgentIntegrationDeps {
    beginAgentConversationLoad(): number
    isCurrentAgentConversationLoad(agentConversationLoadToken: number): boolean
    isCurrentLoad(project: ProjectReference, projectLoadToken: number): boolean
    project(): ProjectReference | null
    refreshSnapshot(workingFolder: string): void
    requireDependencies(): RequiredDataServiceDependencies
    requireFile(path: string): MarkdownFile
    snapshot(): ProjectSnapshot | null
    conversationChanged(cardPath: string): void
}

function isOnStateActionError(error: AgentConversationError) {
    return error.path.startsWith(`${ON_STATE_ACTION_ERROR_PATH_PREFIX}:`)
}

function mergeAgentConversations(existing: AgentConversation[], loaded: AgentConversation[]) {
    const conversationsById = new Map(existing.map((conversation) => [conversation.id, conversation]))
    loaded.forEach((conversation) => conversationsById.set(conversation.id, conversation))

    return [...conversationsById.values()]
}

function cardsForAgentConversationLoading(snapshot: ProjectSnapshot) {
    return snapshot.activeCards
}

async function loadAgentConversationReference(
    task: AgentConversationLoadTask,
    project: ProjectReference,
    storage: StorageService,
): Promise<AgentConversationLoadResult> {
    try {
        const conversation = await loadAgentConversation(storage, project, task.reference)
        if (conversation.cardInternalId !== task.cardInternalId) {
            throw new Error(`Agent conversation belongs to ${conversation.cardInternalId}, not ${task.cardInternalId}`)
        }

        return { cardInternalId: task.cardInternalId, cardPath: task.cardPath, conversation, error: null }
    } catch (error) {
        const message = error instanceof Error ? error.message : 'Agent conversation failed to load'
        telemetryService.captureError(error)

        return {
            cardInternalId: task.cardInternalId,
            cardPath: task.cardPath,
            conversation: null,
            error: { message, path: task.reference },
        }
    }
}

async function resolveAgentConversations(
    cards: ProjectSnapshot['activeCards'],
    project: ProjectReference,
    storage: StorageService,
): Promise<ResolvedAgentConversations> {
    const conversationsByCardInternalId = new Map<string, AgentConversation[]>()
    const errorsByCardPath = new Map<string, AgentConversationError[]>()
    const tasks = cards.flatMap((card) => {
        const cardInternalId = card.header.internalId
        if (!cardInternalId) throw new Error(`Cannot load card conversations without an internal ID: ${card.path}`)

        return card.header.agentLogReferences.map((reference) => ({
            cardInternalId,
            cardPath: card.path,
            reference,
        }))
    })
    const results = await mapWithConcurrency(tasks, AGENT_CONVERSATION_LOAD_CONCURRENCY, async (task) => (
        loadAgentConversationReference(task, project, storage)
    ))

    for (const result of results) {
        if (result.error) {
            errorsByCardPath.set(result.cardPath, [...(errorsByCardPath.get(result.cardPath) ?? []), result.error])
            continue
        }

        const conversations = conversationsByCardInternalId.get(result.cardInternalId) ?? []
        conversationsByCardInternalId.set(result.cardInternalId, [...conversations, result.conversation])
    }

    return { conversationsByCardInternalId, errorsByCardPath }
}

export class AgentIntegration {
    private agentConversationLoadToken: number | null = null
    private completedConversationLoads: Set<string> = new Set()
    private conversationsByCardInternalId: Map<string, AgentConversation[]> = new Map()
    private conversationLoadGeneration = 0
    private conversationLoadsInFlight: Map<string, Promise<void>> = new Map()
    private currentProjectLoadToken: number | null = null
    private readonly dependencies: AgentIntegrationDeps
    private errorsByCardPath: Map<string, AgentConversationError[]> = new Map()
    private projectConversations: AgentConversation[] = []
    private reportedLoadErrorKeys: Set<string> = new Set()
    private readonly addAgentLogReference: (cardPath: string, reference: string) => string | null
    private scheduledRunCleanup: (() => void) | null = null

    constructor(
        dependencies: AgentIntegrationDeps,
        addAgentLogReference: (cardPath: string, reference: string) => string | null,
    ) {
        this.dependencies = dependencies
        this.addAgentLogReference = addAgentLogReference
    }

    reset() {
        this.stopScheduledRunWatch()
        this.resetLoadedConversations()
    }

    resetLoadedConversations() {
        this.dependencies.beginAgentConversationLoad()
        this.agentConversationLoadToken = null
        this.completedConversationLoads.clear()
        this.conversationsByCardInternalId = new Map()
        this.conversationLoadGeneration += 1
        this.conversationLoadsInFlight.clear()
        this.currentProjectLoadToken = null
        this.errorsByCardPath = new Map()
        this.projectConversations = []
        this.reportedLoadErrorKeys.clear()
        agentAcknowledgementService.reset()
    }

    /** Resolves the loaded record matching a conversation, so view changes update the canonical instance. */
    findStoredConversation(conversation: AgentConversation) {
        if (!conversation.cardInternalId) return null

        return (this.conversationsByCardInternalId.get(conversation.cardInternalId) ?? [])
            .find(({ id }) => id === conversation.id) ?? null
    }

    startScheduledRunWatch() {
        this.stopScheduledRunWatch()
        this.scheduledRunCleanup = actionRunRegistry.subscribeActiveRunEvents((event) => {
            try {
                this.handleActionRunEvent(event)
            } catch (error) {
                telemetryService.captureError(error)
            }
        })
    }

    stopScheduledRunWatch() {
        if (!this.scheduledRunCleanup) return

        this.scheduledRunCleanup()
        this.scheduledRunCleanup = null
    }

    async continueAgentConversation(cardPath: string, sourcePath: string) {
        const { config } = this.dependencies.requireDependencies()
        const snapshot = this.dependencies.snapshot()
        const card = [...(snapshot?.activeCards ?? []), ...(snapshot?.backgroundCards ?? [])]
            .find((candidate) => candidate.path === cardPath)
        if (!card) throw new Error(`Cannot continue agent for unknown card: ${cardPath}`)
        if (!card.header.internalId) throw new Error(`Cannot continue agent for card without an internal ID: ${cardPath}`)
        const conversation = (this.conversationsByCardInternalId.get(card.header.internalId) ?? [])
            .find(({ path }) => path === sourcePath)
        if (!conversation) throw new Error(`Unknown agent conversation: ${sourcePath}`)
        const action = conversation.actionId
            ? actionService.getActions().find(({ id }) => id === conversation.actionId)
            : BUILTIN_CUSTOM_PROMPT
        if (!action) throw new Error(`Unknown originating action: ${conversation.actionId}`)

        return runElectronAction(action, fileContext(card, config.cardTypes), { continueFrom: sourcePath })
    }

    private saveAgentConversationReference(cardPath: string, reference: string) {
        return this.addAgentLogReference(cardPath, reference)
    }

    private linkAgentConversationReference(cardPath: string, reference: string) {
        const cardInternalId = this.saveAgentConversationReference(cardPath, reference)
        if (!cardInternalId) throw new Error(`Cannot link a card conversation without an internal ID: ${cardPath}`)
        void this.loadLinkedAgentConversation(cardInternalId, cardPath, reference)
    }

    private async loadLinkedAgentConversation(cardInternalId: string, cardPath: string, reference: string) {
        const project = this.dependencies.project()
        if (!project) return
        const { storage } = this.dependencies.requireDependencies()
        const result = await loadAgentConversationReference({ cardInternalId, cardPath, reference }, project, storage)
        if (result.error) {
            const errors = [...(this.errorsByCardPath.get(cardPath) ?? []), result.error]
            this.errorsByCardPath.set(cardPath, errors)
            this.reportNewAgentLoadErrors(new Map([[cardPath, [result.error]]]))
            this.dependencies.conversationChanged(cardPath)
            return
        }

        this.upsertAgentConversation(cardInternalId, result.conversation)
    }

    async loadAgentConversationsInBackground(snapshot: ProjectSnapshot, project: ProjectReference, projectLoadToken: number) {
        this.prepareProjectConversationLoad(projectLoadToken)
        const cards = cardsForAgentConversationLoading(snapshot)

        const results = await Promise.allSettled([
            this.ensureProjectAgentConversationsLoaded(project, projectLoadToken),
            this.ensureCardGroupLoaded(cards, project, projectLoadToken),
        ])
        for (const result of results) {
            if (result.status !== 'rejected') continue

            dialogService.warning('Agent conversations could not be loaded and were skipped.', { title: 'Some agent conversations were not loaded' })
            telemetryService.captureError(result.reason)
        }
    }

    async ensureAgentConversationsForCard(cardInternalId: string) {
        const project = this.dependencies.project()
        if (!project) throw new Error('Cannot load card conversations before a project is open')
        const projectLoadToken = this.requireProjectLoadToken()
        const identity = AgentIntegration.cardLoadIdentity(cardInternalId)
        const existingLoad = this.conversationLoadsInFlight.get(identity)
        if (existingLoad) {
            await existingLoad

            return this.getAgentConversations(cardInternalId)
        }
        if (this.completedConversationLoads.has(identity)) return this.getAgentConversations(cardInternalId)

        const snapshot = this.dependencies.snapshot()
        const activeCard = snapshot?.activeCards.find(({ header }) => header.internalId === cardInternalId)
        if (activeCard) return this.getAgentConversations(cardInternalId)

        const card = snapshot?.backgroundCards.find(({ header }) => header.internalId === cardInternalId)
        if (!card) throw new Error(`Cannot load conversations for unknown card: ${cardInternalId}`)

        await this.ensureCardGroupLoaded([card], project, projectLoadToken)

        return this.getAgentConversations(cardInternalId)
    }

    async listProjectAgentConversations() {
        const project = this.dependencies.project()
        if (!project) throw new Error('Cannot list project conversations before a project is open')
        const projectLoadToken = this.requireProjectLoadToken()
        await this.ensureProjectAgentConversationsLoaded(project, projectLoadToken)

        return this.projectConversations
    }

    private static cardLoadIdentity(cardInternalId: string) {
        return `card:${cardInternalId}`
    }

    private prepareProjectConversationLoad(projectLoadToken: number) {
        if (this.currentProjectLoadToken === projectLoadToken) return

        this.agentConversationLoadToken = this.dependencies.beginAgentConversationLoad()
        this.completedConversationLoads.clear()
        this.conversationLoadGeneration += 1
        this.conversationLoadsInFlight.clear()
        this.currentProjectLoadToken = projectLoadToken
    }

    private requireProjectLoadToken() {
        if (this.currentProjectLoadToken === null) throw new Error('Agent conversation loading has not started for the current project')

        return this.currentProjectLoadToken
    }

    private async ensureProjectAgentConversationsLoaded(project: ProjectReference, projectLoadToken: number) {
        const identity = 'project'
        if (this.completedConversationLoads.has(identity)) return
        const existingLoad = this.conversationLoadsInFlight.get(identity)
        if (existingLoad) return existingLoad

        const load = async () => {
            const { config, storage } = this.dependencies.requireDependencies()
            const references = await listAgentConversationReferences(storage, project, config.projectFolder)
            const conversations = await mapWithConcurrency(references, AGENT_CONVERSATION_LOAD_CONCURRENCY, async (reference) => (
                loadAgentConversation(storage, project, reference)
            ))
            if (!this.shouldApplyProjectLoad(project, projectLoadToken)) return

            this.projectConversations = conversations.filter(({ cardInternalId }) => cardInternalId === null)
        }

        return this.trackConversationLoad([identity], project, projectLoadToken, load)
    }

    private async ensureCardGroupLoaded(
        cards: ProjectSnapshot['activeCards'],
        project: ProjectReference,
        projectLoadToken: number,
    ) {
        const loads = new Set<Promise<void>>()
        const cardsToLoad = cards.filter((card) => {
            const cardInternalId = card.header.internalId
            if (!cardInternalId) throw new Error(`Cannot load card conversations without an internal ID: ${card.path}`)
            const identity = AgentIntegration.cardLoadIdentity(cardInternalId)
            if (this.completedConversationLoads.has(identity)) return false
            const existingLoad = this.conversationLoadsInFlight.get(identity)
            if (!existingLoad) return true

            loads.add(existingLoad)
            return false
        })
        if (cardsToLoad.length > 0) {
            const identities = cardsToLoad.map(({ header }) => AgentIntegration.cardLoadIdentity(header.internalId as string))
            const load = () => this.resolveAndAttachAgentConversations(cardsToLoad, project, projectLoadToken)
            loads.add(this.trackConversationLoad(identities, project, projectLoadToken, load))
        }

        await Promise.all(loads)
    }

    private trackConversationLoad(
        identities: string[],
        project: ProjectReference,
        projectLoadToken: number,
        load: () => Promise<void>,
    ) {
        const generation = this.conversationLoadGeneration
        const loadPromise = load()
        const trackedPromise = loadPromise.then(() => {
            if (generation !== this.conversationLoadGeneration) return
            if (!this.shouldApplyProjectLoad(project, projectLoadToken)) return

            identities.forEach((identity) => this.completedConversationLoads.add(identity))
        }).finally(() => {
            identities.forEach((identity) => {
                if (this.conversationLoadsInFlight.get(identity) === trackedPromise) {
                    this.conversationLoadsInFlight.delete(identity)
                }
            })
        })
        identities.forEach((identity) => this.conversationLoadsInFlight.set(identity, trackedPromise))

        return trackedPromise
    }

    getAgentConversations(cardInternalId: string) {
        return this.conversationsByCardInternalId.get(cardInternalId) ?? []
    }

    attachAgentConversations(cards: Pick<ProjectSnapshot, 'activeCards' | 'backgroundCards'>) {
        return {
            activeCards: cards.activeCards.map((card) => this.attachCardAgentConversations(card)),
            backgroundCards: cards.backgroundCards.map((card) => this.attachCardAgentConversations(card)),
        }
    }

    private attachCardAgentConversations(card: Card) {
        card.agentConversationErrors = this.errorsByCardPath.get(card.path) ?? []
        card.agentConversations = card.header.internalId
            ? this.conversationsByCardInternalId.get(card.header.internalId) ?? []
            : []

        return card
    }

    /** Applies a persisted conversation returned by an atomic backend update. */
    updateAgentConversation(conversation: AgentConversation) {
        if (!conversation.cardInternalId) return

        this.upsertAgentConversation(conversation.cardInternalId, conversation)
    }

    triggerStateActions(cardPath: string, state: string) {
        const { config } = this.dependencies.requireDependencies()
        const card = this.dependencies.snapshot()?.activeCards.find((currentCard) => currentCard.path === cardPath)
        if (!card) return

        const context = cardContext(card, config.cardTypes)
        const actions = actionService.getActionsForStateTrigger(state, context)
        for (const action of actions) {
            void this.runStateAction(action, context, cardPath)
        }
    }

    private async resolveAndAttachAgentConversations(
        cards: ProjectSnapshot['activeCards'],
        project: ProjectReference,
        projectLoadToken: number,
    ) {
        const { config, storage } = this.dependencies.requireDependencies()
        const resolved = await resolveAgentConversations(cards, project, storage)
        if (!this.shouldApplyProjectLoad(project, projectLoadToken)) return

        for (const [cardInternalId, conversations] of resolved.conversationsByCardInternalId) {
            const existing = this.conversationsByCardInternalId.get(cardInternalId) ?? []
            this.conversationsByCardInternalId.set(cardInternalId, mergeAgentConversations(existing, conversations))
        }
        this.replaceResolvedAgentErrors(cards, resolved.errorsByCardPath)
        this.reportNewAgentLoadErrors(resolved.errorsByCardPath)
        this.dependencies.refreshSnapshot(config.workingFolder)
        cards.forEach(({ path }) => this.dependencies.conversationChanged(path))
        for (const [cardInternalId, conversations] of resolved.conversationsByCardInternalId) {
            const actionIds = conversations.flatMap(({ actionId }) => actionId ? [actionId] : [])
            agentAcknowledgementService.announceConversationsChanged(cardInternalId, actionIds)
        }
    }

    private shouldApplyProjectLoad(project: ProjectReference, projectLoadToken: number) {
        return this.currentProjectLoadToken === projectLoadToken
            && this.agentConversationLoadToken !== null
            && this.dependencies.isCurrentAgentConversationLoad(this.agentConversationLoadToken)
            && this.dependencies.isCurrentLoad(project, projectLoadToken)
    }

    private replaceResolvedAgentErrors(cards: ProjectSnapshot['activeCards'], resolvedErrors: Map<string, AgentConversationError[]>) {
        const errors = new Map(this.errorsByCardPath)
        for (const { path: cardPath } of cards) {
            const loadedErrors = resolvedErrors.get(cardPath) ?? []
            const existingErrors = errors.get(cardPath) ?? []
            const onStateErrors = existingErrors.filter(isOnStateActionError)
            const nextErrors = [...loadedErrors, ...onStateErrors]
            if (nextErrors.length === 0) {
                errors.delete(cardPath)
                continue
            }

            errors.set(cardPath, nextErrors)
        }

        this.errorsByCardPath = errors
    }

    private reportNewAgentLoadErrors(errorsByCardPath: Map<string, AgentConversationError[]>) {
        const newErrors: AgentConversationError[] = []
        for (const [cardPath, errors] of errorsByCardPath) {
            for (const error of errors) {
                const key = `${cardPath}:${error.path}:${error.message}`
                if (this.reportedLoadErrorKeys.has(key)) continue

                this.reportedLoadErrorKeys.add(key)
                newErrors.push(error)
            }
        }
        if (newErrors.length === 0) return

        const paths = newErrors.map(({ path }) => path).join(', ')
        dialogService.warning(`Some agent conversations could not be loaded and were skipped: ${paths}`, {title: 'Some agent conversations were not loaded'})
    }

    private async runStateAction(action: ActionDefinition, context: ActionContext, cardPath: string) {
        try {
            const result = await runElectronAction(action, context, {}, undefined, false)
            if (result.status === 'completed') return

            const failedLog = result.logs.find((log) => log.status === 'failed')
            this.recordCardAgentError(cardPath, action.id, failedLog?.message ?? `${action.label} failed`)
        } catch (error) {
            this.recordCardAgentError(cardPath, action.id, error instanceof Error ? error.message : `${action.label} failed`)
        }
    }

    private recordCardAgentError(cardPath: string, actionName: string, message: string) {
        const path = `${ON_STATE_ACTION_ERROR_PATH_PREFIX}:${actionName}`
        const { config } = this.dependencies.requireDependencies()
        this.errorsByCardPath.set(cardPath, [...(this.errorsByCardPath.get(cardPath) ?? []), { message, path }])
        this.dependencies.refreshSnapshot(config.workingFolder)
        this.dependencies.conversationChanged(cardPath)
    }

    private handleActionRunEvent(event: ActionRunEvent) {
        if (
            event.type === 'update'
            && event.update.kind === 'agentStarted'
            && event.context.kind === 'card'
            && event.context.file
        ) {
            this.saveAgentConversationReference(event.context.file, event.update.conversation.path)
        }
        if (event.type === 'action') this.linkActionConversation(event)
    }

    private linkActionConversation(event: ActionRunEvent) {
        if (event.type !== 'action' || event.status === 'running' || !event.context.file || !event.reference) return

        this.linkAgentConversationReference(event.context.file, event.reference)
    }

    private upsertAgentConversation(cardInternalId: string, conversation: AgentConversation) {
        const { config } = this.dependencies.requireDependencies()
        const conversations = this.conversationsByCardInternalId.get(cardInternalId) ?? []
        const nextConversations = conversations.some((current) => current.id === conversation.id)
            ? conversations.map((current) => (current.id === conversation.id ? conversation : current))
            : [...conversations, conversation]
        this.conversationsByCardInternalId.set(cardInternalId, nextConversations)
        this.dependencies.refreshSnapshot(config.workingFolder)
        const card = this.dependencies.snapshot()?.activeCards.find(({ header }) => header.internalId === cardInternalId)
            ?? this.dependencies.snapshot()?.backgroundCards.find(({ header }) => header.internalId === cardInternalId)
        if (card) this.dependencies.conversationChanged(card.path)
        const actionIds = conversation.actionId ? [conversation.actionId] : []
        agentAcknowledgementService.announceConversationsChanged(cardInternalId, actionIds)
    }

}

import { AUTO_COMMIT_DELAY_MS, type CommitRequest, type MarkdownFile } from './data_types'

import { markdownParsingService } from '../services/data/markdown_parsing_service'
import type { OpenDocumentSaveReference } from '../services/open_files_service'
import type { Card } from './data_types'

type DelayId = number

interface CommitBatcherOperations {
    commitFiles(request: CommitRequest): Promise<unknown>
    pushCommittedFiles(request: CommitRequest): Promise<unknown>
    requireCardByInternalId(internalId: string): Card
}

export const COMMIT_BATCHER_FLUSH_FAILED_EVENT = 'flushFailed'
export const COMMIT_BATCHER_PENDING_CHANGED_EVENT = 'pendingChanged'

interface PendingFileChange {
    change: CommitChange
    fromPath: string
    moveSource: boolean
    onCommitted?: (fromPath: string, toPath: string) => void
    onPersisted?: () => void
    saveReference?: OpenDocumentSaveReference
}

export interface CommitFileChange extends MarkdownFile {
    onPersisted?: () => void
    saveReference?: OpenDocumentSaveReference
}

export interface CommitCardChange {
    cardInternalId: string
    onPersisted?: () => void
    path: string
    saveReference?: OpenDocumentSaveReference
    targetPath?: string
}

export type CommitChange = CommitFileChange | CommitCardChange

function isCardChange(change: CommitChange): change is CommitCardChange {
    return 'cardInternalId' in change
}

function changePath(change: CommitChange) {
    return isCardChange(change) ? change.targetPath ?? change.path : change.path
}

interface SerializedChange {
    card: Card | null
    file: MarkdownFile
}

function serializeChange(change: CommitChange, cardOperations: CommitBatcherOperations): SerializedChange {
    if (!isCardChange(change)) {
        const file = {
            content: change.content,
            ...(change.encoding ? { encoding: change.encoding } : {}),
            path: change.path,
            ...(change.sha ? { sha: change.sha } : {}),
        }

        return { card: null, file }
    }

    const card = cardOperations.requireCardByInternalId(change.cardInternalId)
    const file = { ...markdownParsingService.serializeCard(card), path: changePath(change) }

    return { card, file }
}

export class CommitBatcher extends EventTarget {
    private activeFlush: Promise<void> | null
    private automaticFlushDeferrals: number
    private readonly cardOperations: CommitBatcherOperations
    private readonly delayMs
    private pendingBranch: string | null
    private readonly pendingChanges
    private readonly pendingMessagesByPath
    private scheduledDelayId: DelayId | null

    constructor(cardOperations: CommitBatcherOperations, delayMs = AUTO_COMMIT_DELAY_MS) {
        super()
        this.activeFlush = null
        this.automaticFlushDeferrals = 0
        this.cardOperations = cardOperations
        this.delayMs = delayMs
        this.pendingBranch = null
        this.pendingChanges = new Map<string, PendingFileChange>()
        this.pendingMessagesByPath = new Map<string, string[]>()
        this.scheduledDelayId = null
    }

    schedule(branch: string, changes: CommitChange[], message: string) {
        this.pendingBranch = branch
        changes.forEach((change) => {
            const path = changePath(change)
            this.pendingChanges.set(path, {
                change,
                fromPath: path,
                moveSource: false,
                onPersisted: change.onPersisted,
                saveReference: change.saveReference,
            })
            this.addPendingMessage(path, message)
        })

        this.scheduleFlush()
    }

    schedulePathChange(
        branch: string,
        fromPath: string,
        change: CommitChange,
        message: string,
        onCommitted: (fromPath: string, toPath: string) => void,
        sourceExists = true,
    ) {
        this.pendingBranch = branch
        this.pendingChanges.set(fromPath, {
            change,
            fromPath,
            moveSource: sourceExists,
            onCommitted,
            onPersisted: change.onPersisted,
            saveReference: change.saveReference,
        })
        this.addPendingMessage(fromPath, message)

        this.scheduleFlush()
    }

    private scheduleFlush() {
        this.clearScheduledDelay()
        if (this.automaticFlushDeferrals > 0) {
            this.dispatchEvent(new Event(COMMIT_BATCHER_PENDING_CHANGED_EVENT))
            return
        }
        this.scheduledDelayId = window.setTimeout(this.createFlushCallback(), this.delayMs)
        this.dispatchEvent(new Event(COMMIT_BATCHER_PENDING_CHANGED_EVENT))
    }

    /** Pauses timer-driven flushes while one caller adds fields that must share a card version. */
    deferAutomaticFlush() {
        this.automaticFlushDeferrals += 1
        this.clearScheduledDelay()
        let released = false

        return () => {
            if (released) return

            released = true
            this.automaticFlushDeferrals -= 1
            if (this.automaticFlushDeferrals === 0 && this.hasPending()) this.scheduleFlush()
        }
    }

    hasPending() {
        return this.pendingChanges.size > 0 && this.pendingBranch !== null
    }

    hasPendingFile(path: string) {
        return [...this.pendingChanges.values()].some(({ change, fromPath }) => (
            fromPath === path || changePath(change) === path
        ))
    }

    discardPendingFile(path: string) {
        const entry = [...this.pendingChanges.entries()].find(([, { change, fromPath }]) => (
            fromPath === path || changePath(change) === path
        ))
        if (!entry) return

        const [changeKey] = entry
        this.pendingChanges.delete(changeKey)

        this.pendingMessagesByPath.delete(changeKey)
        if (this.pendingChanges.size === 0) {
            this.pendingBranch = null
            this.clearScheduledDelay()
        }
        this.dispatchEvent(new Event(COMMIT_BATCHER_PENDING_CHANGED_EVENT))
    }

    async flush() {
        if (this.activeFlush) {
            await this.activeFlush
            if (this.hasPending()) await this.flush()
            return
        }
        if (!this.hasPending()) return

        this.clearScheduledDelay()
        const pendingChanges = [...this.pendingChanges.values()]
        const serializedChanges = new Map(
            pendingChanges.map((change) => [change, serializeChange(change.change, this.cardOperations)]),
        )
        const files = pendingChanges
            .filter(({ moveSource }) => !moveSource)
            .map((change) => (serializedChanges.get(change) as SerializedChange).file)
        const moves = pendingChanges
            .filter(({ moveSource }) => moveSource)
            .map((change) => {
                const { file } = serializedChanges.get(change) as SerializedChange

                return {
                    content: file.content,
                    ...(file.encoding ? { encoding: file.encoding } : {}),
                    fromPath: change.fromPath,
                    ...(file.sha ? { sha: file.sha } : {}),
                    toPath: file.path,
                }
            })
        const request = {
            branch: this.pendingBranch as string,
            files,
            message: this.createCommitMessage(),
            ...(moves.length > 0 ? { moves } : {}),
        }

        this.activeFlush = this.commitSnapshot(request, pendingChanges, serializedChanges)
        try {
            await this.activeFlush
        } finally {
            this.activeFlush = null
        }
    }

    private addPendingMessage(path: string, message: string) {
        const messages = this.pendingMessagesByPath.get(path) ?? []
        if (messages.includes(message)) return

        this.pendingMessagesByPath.set(path, [...messages, message])
    }

    private async commitSnapshot(
        request: CommitRequest,
        changes: PendingFileChange[],
        serializedChanges: Map<PendingFileChange, SerializedChange>,
    ) {
        await this.cardOperations.commitFiles(request)
        for (const change of changes) {
            const { fromPath, onCommitted, onPersisted, saveReference } = change
            const { card, file } = serializedChanges.get(change) as SerializedChange
            const current = this.pendingChanges.get(fromPath)
            if (current === change) {
                this.pendingChanges.delete(fromPath)
                this.pendingMessagesByPath.delete(fromPath)
            } else if (current && file.path !== fromPath) {
                this.pendingChanges.delete(fromPath)
                this.pendingChanges.set(file.path, { ...current, fromPath: file.path, moveSource: true })
                const messages = this.pendingMessagesByPath.get(fromPath)
                this.pendingMessagesByPath.delete(fromPath)
                if (messages) this.pendingMessagesByPath.set(file.path, messages)
            }
            if (card) markdownParsingService.acknowledgeSerializedCard(card, file)
            saveReference?.acknowledge()
            onPersisted?.()
            onCommitted?.(fromPath, file.path)
        }
        if (this.pendingChanges.size === 0) this.pendingBranch = null
        this.dispatchEvent(new Event(COMMIT_BATCHER_PENDING_CHANGED_EVENT))
        await this.cardOperations.pushCommittedFiles(request)
    }

    private createCommitMessage() {
        const messages = [...this.pendingMessagesByPath.values()].flat()
        const distinctMessages = [...new Set(messages)]
        if (distinctMessages.length === 1) return distinctMessages[0]

        const body = distinctMessages.map((message) => `- ${message}`).join('\n')

        return `Update ${this.pendingChanges.size} files\n\n${body}`
    }

    private createFlushCallback() {
        return () => {
            void this.flush().catch((error: unknown) => {
                this.dispatchEvent(new CustomEvent(COMMIT_BATCHER_FLUSH_FAILED_EVENT, { detail: error }))
            })
        }
    }

    private clearScheduledDelay() {
        if (this.scheduledDelayId === null) return

        window.clearTimeout(this.scheduledDelayId)
        this.scheduledDelayId = null
    }
}

