    private requireProjectLoadToken() {
        if (this.currentProjectLoadToken === null) throw new Error('Agent conversation loading has not started for the current project')

        return this.currentProjectLoadToken
    }

    private async ensureProjectAgentConversationsLoaded(project: ProjectReference, projectLoadToken: number) {
        const identity = 'project'
        if (this.completedConversationLoads.has(identity)) return
        const existingLoad = this.conversationLoadsInFlight.get(identity)
        if (existingLoad) return existingLoad

        const load = async () => {
            const { config, storage } = this.dependencies.requireDependencies()
            const references = await listAgentConversationReferences(storage, project, config.projectFolder)
            const conversations = await mapWithConcurrency(references, AGENT_CONVERSATION_LOAD_CONCURRENCY, async (reference) => (
                loadAgentConversation(storage, project, reference)
            ))
            if (!this.shouldApplyProjectLoad(project, projectLoadToken)) return

            this.projectConversations = conversations.filter(({ cardInternalId }) => cardInternalId === null)
        }

        return this.trackConversationLoad([identity], project, projectLoadToken, load)
    }

    private async ensureCardGroupLoaded(
        cards: ProjectSnapshot['activeCards'],
        project: ProjectReference,
        projectLoadToken: number,
    ) {
        const loads = new Set<Promise<void>>()
        const cardsToLoad = cards.filter((card) => {
            const cardInternalId = card.header.internalId
            if (!cardInternalId) throw new Error(`Cannot load card conversations without an internal ID: ${card.path}`)
            const identity = AgentIntegration.cardLoadIdentity(cardInternalId)
            if (this.completedConversationLoads.has(identity)) return false
            const existingLoad = this.conversationLoadsInFlight.get(identity)
            if (!existingLoad) return true

            loads.add(existingLoad)
            return false
        })
        if (cardsToLoad.length > 0) {
            const identities = cardsToLoad.map(({ header }) => AgentIntegration.cardLoadIdentity(header.internalId as string))
            const load = () => this.resolveAndAttachAgentConversations(cardsToLoad, project, projectLoadToken)
            loads.add(this.trackConversationLoad(identities, project, projectLoadToken, load))
        }

        await Promise.all(loads)
    }

    private trackConversationLoad(
        identities: string[],
        project: ProjectReference,
        projectLoadToken: number,
        load: () => Promise<void>,
    ) {
        const generation = this.conversationLoadGeneration
        const loadPromise = load()
        const trackedPromise = loadPromise.then(() => {
            if (generation !== this.conversationLoadGeneration) return
            if (!this.shouldApplyProjectLoad(project, projectLoadToken)) return

            identities.forEach((identity) => this.completedConversationLoads.add(identity))
        }).finally(() => {
            identities.forEach((identity) => {
                if (this.conversationLoadsInFlight.get(identity) === trackedPromise) {
                    this.conversationLoadsInFlight.delete(identity)
                }
            })
        })
        identities.forEach((identity) => this.conversationLoadsInFlight.set(identity, trackedPromise))

        return trackedPromise
    }

    getAgentConversations(cardInternalId: string) {
        return this.conversationsByCardInternalId.get(cardInternalId) ?? []
    }

    attachAgentConversations(cards: Pick<ProjectSnapshot, 'activeCards' | 'backgroundCards'>) {
        return {
            activeCards: cards.activeCards.map((card) => this.attachCardAgentConversations(card)),
            backgroundCards: cards.backgroundCards.map((card) => this.attachCardAgentConversations(card)),
        }
    }

    private attachCardAgentConversations(card: Card) {
        card.agentConversationErrors = this.errorsByCardPath.get(card.path) ?? []
        card.agentConversations = card.header.internalId
            ? this.conversationsByCardInternalId.get(card.header.internalId) ?? []
            : []

        return card
    }

    /** Applies a persisted conversation returned by an atomic backend update. */
    updateAgentConversation(conversation: AgentConversation) {
        if (!conversation.cardInternalId) return

        this.upsertAgentConversation(conversation.cardInternalId, conversation)
    }

    triggerStateActions(cardPath: string, state: string) {
        const { config } = this.dependencies.requireDependencies()
        const card = this.dependencies.snapshot()?.activeCards.find((currentCard) => currentCard.path === cardPath)
        if (!card) return

        const context = cardContext(card, config.cardTypes)
        const actions = actionService.getActionsForStateTrigger(state, context)
        for (const action of actions) {
            void this.runStateAction(action, context, cardPath)
        }
    }

    private async resolveAndAttachAgentConversations(
        cards: ProjectSnapshot['activeCards'],
        project: ProjectReference,
        projectLoadToken: number,
    ) {
        const { config, storage } = this.dependencies.requireDependencies()
        const resolved = await resolveAgentConversations(cards, project, storage)
        if (!this.shouldApplyProjectLoad(project, projectLoadToken)) return

        for (const [cardInternalId, conversations] of resolved.conversationsByCardInternalId) {
            const existing = this.conversationsByCardInternalId.get(cardInternalId) ?? []
            this.conversationsByCardInternalId.set(cardInternalId, mergeAgentConversations(existing, conversations))
        }
        this.replaceResolvedAgentErrors(cards, resolved.errorsByCardPath)
        this.reportNewAgentLoadErrors(resolved.errorsByCardPath)
        this.dependencies.refreshSnapshot(config.workingFolder)
        cards.forEach(({ path }) => this.dependencies.conversationChanged(path))
        for (const [cardInternalId, conversations] of resolved.conversationsByCardInternalId) {
            const actionIds = conversations.flatMap(({ actionId }) => actionId ? [actionId] : [])
            agentAcknowledgementService.announceConversationsChanged(cardInternalId, actionIds)
        }
    }

    private shouldApplyProjectLoad(project: ProjectReference, projectLoadToken: number) {
        return this.currentProjectLoadToken === projectLoadToken
            && this.agentConversationLoadToken !== null
            && this.dependencies.isCurrentAgentConversationLoad(this.agentConversationLoadToken)
            && this.dependencies.isCurrentLoad(project, projectLoadToken)
    }

    private replaceResolvedAgentErrors(cards: ProjectSnapshot['activeCards'], resolvedErrors: Map<string, AgentConversationError[]>) {
        const errors = new Map(this.errorsByCardPath)
        for (const { path: cardPath } of cards) {
            const loadedErrors = resolvedErrors.get(cardPath) ?? []
            const existingErrors = errors.get(cardPath) ?? []
            const onStateErrors = existingErrors.filter(isOnStateActionError)
            const nextErrors = [...loadedErrors, ...onStateErrors]
            if (nextErrors.length === 0) {
                errors.delete(cardPath)
                continue
            }

            errors.set(cardPath, nextErrors)
        }
import type {
    AgentConversation,
    ProjectReference,
    RunningAgent,
    AgentRunEvent,
    StorageService,
} from '../../data/data_types'
import { register } from '../service_injector'
import { parseAgentConversation } from '../../../../shared/agent_conversations.mjs'

type Listener = () => void

export function parseAgentConversationLog(content: string, referencePath: string): AgentConversation {
    return parseAgentConversation(content, referencePath)
}

/** Discover persisted agent-conversation references through any storage implementation. */
export async function listAgentConversationReferences(storage: StorageService, project: ProjectReference, projectFolder: string) {
    if (!storage.listAgentConversationReferences) throw new Error('Agent conversation listing requires a storage bridge')

    return storage.listAgentConversationReferences(project, projectFolder)
}

export async function loadAgentConversation(storage: StorageService, project: ProjectReference, path: string) {
    if (!storage.loadAgentConversation) throw new Error('Agent conversation loading requires a storage bridge')

    return storage.loadAgentConversation(project, path)
}

export class AgentConversationService extends EventTarget {
    private runningAgents: RunningAgent[]

    constructor() {
        super()
        this.runningAgents = []
        register('agentConversationService', this)
    }

    getRunningAgents() {
        return this.runningAgents
    }

    observeRunEvent(event: AgentRunEvent, label: string) {
        if (event.type === 'started') {
            if (!this.runningAgents.some((agent) => agent.id === event.runId)) {
                this.setRunningAgents([...this.runningAgents, { id: event.runId, label }])
            }

            return
        }

        if (event.type === 'closed') this.removeRunningAgent(event.runId)
    }

    subscribe(listener: Listener) {
        this.addEventListener('changed', listener)

        return () => this.removeEventListener('changed', listener)
    }

    private setRunningAgents(runningAgents: RunningAgent[]) {
        this.runningAgents = runningAgents
        this.dispatchEvent(new CustomEvent('changed'))
    }

    private removeRunningAgent(runId: string) {
        this.setRunningAgents(this.runningAgents.filter((agent) => agent.id !== runId))
    }
}

export const agentConversationService = new AgentConversationService()
    onMergeConflictSessionChanged?(callback: (session: MergeConflictSession | null) => void): () => void
    rescanMergeConflict?(request: MergeConflictSessionRequest): Promise<MergeConflictSession>
    moveFiles(request: MoveFilesRequest): Promise<void>
    parkWorktree?(request: WorktreeOperationRequest): Promise<void>
    prepareWorktree?(request: PrepareWorktreeRequest): Promise<void>
    pull?(project: ProjectReference): Promise<void>
    pullWorktree?(request: WorktreeOperationRequest): Promise<void>
    rebaseWorktree?(request: WorktreeOperationRequest): Promise<WorktreeOperationOutcome>
    push(project: ProjectReference): Promise<void>
    pushWorktree?(request: WorktreeOperationRequest): Promise<void>
    refreshWorktrees?(project: ProjectReference): Promise<void>
    saveActionSchedules?(project: ProjectReference, actionsFolder: string, schedules: ActionSchedule[]): Promise<ActionSchedule[]>
    saveProjectConfig(project: ProjectReference, config: ProjectConfig): Promise<void>
    removeWorktree?(project: ProjectReference, folderPath: string): Promise<void>
    stopAgent?(project: ProjectReference, runId: string): Promise<void>
    watchProject?(
        project: ProjectReference,
        onChange: (event: ProjectWatchEvent) => void,
        onRestored: () => void,
    ): () => void
}

const BUG_CARD_COLOR = '#d32f2f'

export const DEFAULT_COLUMN_ACCENTS = ['#9c4dcc', '#29a8e0', '#ed6c02', '#f9a825', '#43a047']

/** Resolve the repeating default accent assigned by configured column position. */
export function defaultColumnAccent(index: number) {
    if (!Number.isInteger(index) || index < 0) throw new Error(`Invalid column index: ${index}`)

    return DEFAULT_COLUMN_ACCENTS[index % DEFAULT_COLUMN_ACCENTS.length]
}

export const DEFAULT_CARD_TYPES: CardTypeConfig[] = [
    { color: DEFAULT_COLOR_SCHEME.primary.regular, idPrefix: 'F', label: 'Feature', type: 'feature' },
    { color: DEFAULT_COLOR_SCHEME.secondary.regular, idPrefix: 'J', label: 'Job', type: 'job' },
    { color: BUG_CARD_COLOR, idPrefix: 'B', label: 'Bug', type: 'bug' },
]

export const DEFAULT_STATES: StateConfig[] = [
    { alwaysVisible: true, color: defaultColumnAccent(0), state: 'new' },
    { alwaysVisible: true, color: defaultColumnAccent(1), state: 'design' },
    { alwaysVisible: true, color: defaultColumnAccent(2), state: 'ready for implementation' },
    { alwaysVisible: true, color: defaultColumnAccent(3), state: 'to fix' },
    { alwaysVisible: true, color: defaultColumnAccent(4), state: 'ready' },
]

export const DEFAULT_CARD_BODY_TEMPLATE = '# Goal\n\n# Current status\n\n# Details\n\n# Tasks'

function normalizeFolderPath(folderPath: string) {
    return folderPath.replace(/\\/gu, '/').replace(/^\/+|\/+$/gu, '')
}

function joinProjectFolderPath(projectFolder: string, folderPath: string) {
    const normalizedProjectFolder = normalizeFolderPath(projectFolder)
    const normalizedFolderPath = normalizeFolderPath(folderPath)

    return normalizedProjectFolder.length > 0 ? `${normalizedProjectFolder}/${normalizedFolderPath}` : normalizedFolderPath
}

export function resolveProjectConfigPaths(config: ProjectConfig): ProjectConfig {
    return {
        ...config,
        actionsFolder: joinProjectFolderPath(config.projectFolder, config.actionsFolder),
        archivedFolder: joinProjectFolderPath(config.projectFolder, config.archivedFolder),
        releasesFolder: joinProjectFolderPath(config.projectFolder, config.releasesFolder),
        workingFolder: joinProjectFolderPath(config.projectFolder, config.workingFolder),
    }
}

export const DEFAULT_PROJECT_CONFIG: ProjectConfig = {
    actionsFolder: DEFAULT_ACTIONS_FOLDER,
    archivedFolder: DEFAULT_ARCHIVED_FOLDER,
    backgroundShade: 'neutral',
    cardBodyTemplate: DEFAULT_CARD_BODY_TEMPLATE,
    cardSeparator: DEFAULT_CARD_SEPARATOR,
    cardTypes: DEFAULT_CARD_TYPES,
    diffCommand: DEFAULT_DIFF_COMMAND,
    projectFolder: DEFAULT_PROJECT_FOLDER,
    pushMode: 'manual',
    releasesFolder: DEFAULT_RELEASES_FOLDER,
    states: DEFAULT_STATES,
    workingFolder: DEFAULT_WORKING_FOLDER,
}

